INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C1','kor',1,1,'u5',1,'상대에 따라 달라지는 인사말 — 친구·동생에게는 「안녕?·고마워.」, 웃어른께는 「안녕하세요?·고맙습니다.」처럼 같은 인사도 상대에 따라 말이 달라짐을 알고 알맞게 고르기',ARRAY['2국01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C2','kor',1,1,'u5',1,'하루 생활 속 인사말 — 아침에 일어나서·집을 나설 때·돌아왔을 때·밥 먹기 전과 뒤·잠자기 전에 하는 인사말을 때에 맞게 쓰기(다녀오겠습니다 ↔ 다녀왔습니다)',ARRAY['2국01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C3','kor',1,1,'u5',1,'인사하는 마음과 바른 자세 — 반가운 마음을 담아 상대를 바라보고, 웃어른께는 손을 빼고 고개 숙여 공손히 인사하며, 인사하면 서로 가까워짐을 알기',ARRAY['2국01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C4','kor',1,1,'u5',3,'상황에 알맞은 인사말 — 도움을 받았을 때 고마움, 잘못했을 때 사과, 좋은 일에 축하, 헤어질 때 작별 인사처럼 어떤 일이 있었는지 살펴 알맞은 인사말 고르기',ARRAY['2국01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C5','kor',1,1,'u5',3,'인사 주고받기와 역할놀이 — 받은 인사에 알맞게 대답하고(미안해 → 괜찮아, 축하해 → 고마워), 맡은 역할에 맞는 인사말을 차례를 지켜 주고받기',ARRAY['2국01-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C6','kor',1,1,'u5',5,'동시를 듣고 내용 알기 — 인사말이 담긴 동시를 끝까지 듣고 언제, 누구에게, 무엇이라고 인사했는지와 담긴 마음을 알기',ARRAY['2국02-05']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C7','kor',1,1,'u5',5,'되풀이되는 말과 리듬 — 동시에서 되풀이되는 말을 찾아 리듬을 살려 또박또박 따라 읽고 번갈아 읽으며, 틀(「(     )도 잘 자요」)에 맞게 바꿔 쓰기',ARRAY['2국02-05']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C8','kor',1,1,'u5',7,'이야기를 듣고 내용 알기 — 「사슴과 뿔」을 듣고 일어난 일과 그 까닭(뿔이 나뭇가지에 걸림·다리 덕분에 달아남), 인물의 마음이 바뀐 까닭을 알기',ARRAY['2국04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C9','kor',1,1,'u5',7,'글자와 소리가 다른 낱말 — 앞 글자 받침 뒤에 ㅇ으로 시작하는 글자가 오면 받침이 그 자리로 넘어가 소리 남을 알고(악어 [아거]), 받침이 없거나 ㅇ 받침이면 글자와 소리가 같음을 가려 바르게 읽기',ARRAY['2국04-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u5-C10','kor',1,1,'u5',9,'여러 상황에서 인사하기 — 전학·작별·위로·전화 끊기·졸업처럼 생활 속 여러 상황에서 알맞은 인사말을 떠올려 놀이로 주고받고 생활에서 실천하기',ARRAY['2국01-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X01','kor',1,'u5',ARRAY['K1-1-u5-C1']::text[],'인사하는 상대(친구·동생인지 웃어른인지)를 살피지 않고 같은 말을 쓴다 — 웃어른께 「안녕?·고마워.」, 동생에게 「안녕히 주무세요.」','인사하기 전에 「누구에게?」를 먼저 묻기 — 웃어른께는 「~요·~습니다」로 끝나는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X02','kor',1,'u5',ARRAY['K1-1-u5-C2']::text[],'나갈 때와 들어올 때 인사(다녀오겠습니다 ↔ 다녀왔습니다)를 바꿔 쓴다','「오겠습니다」는 이제 갈 때, 「왔습니다」는 다 돌아왔을 때 — 문 앞에서 몸을 돌려 보며 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X03','kor',1,'u5',ARRAY['K1-1-u5-C2','K1-1-u5-C4']::text[],'언제인지, 어떤 일이 있었는지 살피지 않고 다른 때의 인사말을 고른다(아침에 「안녕히 주무세요.」, 먹기 전에 「잘 먹었습니다.」)','장면을 떠올려 「지금은 언제지? 무슨 일이 있었지?」 두 가지를 먼저 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X04','kor',1,'u5',ARRAY['K1-1-u5-C3']::text[],'인사말만 맞으면 된다고 여겨 자세·표정·마음(주머니에 손, 딴 곳 보기, 중얼거리기)을 살피지 않는다','거울 앞에서 손 빼기 · 눈 보기 · 밝은 목소리 세 가지를 하나씩 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X05','kor',1,'u5',ARRAY['K1-1-u5-C4']::text[],'고마운 일과 미안한 일을 헷갈려 인사말을 바꿔 쓴다(도움 받고 「미안해.」, 부딪치고 「고마워.」)','「내가 받았나, 내가 잘못했나?」 — 받았으면 고마워, 잘못했으면 미안해') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X06','kor',1,'u5',ARRAY['K1-1-u5-C4','K1-1-u5-C10']::text[],'기쁜 일과 속상한 일을 거꾸로 보고 인사한다(다친 친구에게 「축하해.」, 상 받은 친구에게 「미안해.」)','친구 얼굴을 떠올려 「기쁠까, 속상할까?」 — 기쁘면 축하, 속상하면 위로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X07','kor',1,'u5',ARRAY['K1-1-u5-C4']::text[],'헤어질 때 떠나는 사람과 남는 사람의 인사를 헷갈린다(떠나면서 「잘 가.」, 남으면서 「안녕히 계세요.」)','내가 떠나면 「안녕히 계세요」, 상대가 떠나면 「안녕히 가세요·잘 가」 — 누가 움직이는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X08','kor',1,'u5',ARRAY['K1-1-u5-C5']::text[],'받은 인사에 대답하지 않거나 맞지 않는 대답을 하고, 주고받을 때 차례를 지키지 않는다','친구 말을 끝까지 듣고 짝 말 떠올리기 — 미안해 ↔ 괜찮아, 축하해 ↔ 고마워') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X09','kor',1,'u5',ARRAY['K1-1-u5-C6']::text[],'동시를 끝까지 듣지 않아 언제·누구에게 한 인사인지 잘못 말하거나 나오지 않은 대상을 말한다','한 줄씩 들으며 「누구에게?」를 손가락으로 꼽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X10','kor',1,'u5',ARRAY['K1-1-u5-C7']::text[],'되풀이되는 말을 찾지 못하거나 리듬 없이 한 글자씩 끊어 읽는다','되풀이되는 말에 동그라미 치고, 그 말을 손뼉 치며 같은 가락으로 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X11','kor',1,'u5',ARRAY['K1-1-u5-C7']::text[],'바꿔 쓸 때 틀(「(     )도 잘 자요」)을 깨뜨리거나 뜻이 맞지 않는 말을 넣는다','빈칸만 바꾸고 나머지는 그대로 — 바꾼 줄을 원래 줄 아래에 나란히 써 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X12','kor',1,'u5',ARRAY['K1-1-u5-C8']::text[],'이야기에서 일어난 일과 그 까닭을 바꿔 말하거나 나오지 않은 일을 말한다(사슴이 다리를 다쳐 못 움직였다)','「무슨 일이? 왜?」를 이야기 차례대로 손가락으로 짚으며 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X13','kor',1,'u5',ARRAY['K1-1-u5-C9']::text[],'받침이 뒤 ㅇ 자리로 넘어가는 낱말을 글자대로 읽는다(악어를 [악어])','앞 받침에 손가락을 대고 뒤 ㅇ 자리로 옮겨 이어 읽기 — 악어 → [아거]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X14','kor',1,'u5',ARRAY['K1-1-u5-C9']::text[],'받침을 뒤로 넘기면서 앞 글자에도 남겨 두 번 읽거나 받침을 아예 빠뜨린다([악거]·[아어])','받침은 한 번만 — 앞 글자에서 빼서 뒤 글자에 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X15','kor',1,'u5',ARRAY['K1-1-u5-C9']::text[],'받침이 없거나 ㅇ 받침인 낱말도 소리가 바뀐다고 여긴다(다리미·강아지의 소리가 달라진다)','「앞 받침 있음 + 뒤 ㅇ」 둘 다 맞을 때만 넘어가요 — ㅇ 받침은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u5-X16','kor',1,'u5',ARRAY['K1-1-u5-C4']::text[],'상대만 보고 무슨 일이 있는지(생신·선물·상)를 놓쳐 늘 하던 인사말만 고른다','「누구에게?」 다음에 「무슨 일?」까지 묻기 — 생신이면 축하, 선물이면 고마움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#1','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C1',1,'mc','auto','만났을 때 친구에게 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":1,"concept":"K1-1-u5-C1","difficulty":1,"kind":"mc","stem":"만났을 때 친구에게 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"안녕?","correct":true},{"t":"잘 자.","mis":"K1-1-u5-X03"},{"t":"미안해.","mis":"K1-1-u5-X03"}],"explanation":["만났을 때 친구에게는 「안녕?」 하고 인사해요.","다른 인사말은 하는 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"👋"},"variant_rule":{"greet":{"ask":"say","to":"friend","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#2','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C1',1,'mc','auto','만났을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":2,"concept":"K1-1-u5-C1","difficulty":1,"kind":"mc","stem":"만났을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"안녕하세요?","correct":true},{"t":"안녕?","mis":"K1-1-u5-X01"},{"t":"고맙습니다.","mis":"K1-1-u5-X03"}],"explanation":["만났을 때 웃어른께는 「안녕하세요?」 하고 인사해요.","「안녕?」은 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"👋"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#3','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C2',1,'mc','auto','아침에 일어났을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":3,"concept":"K1-1-u5-C2","difficulty":1,"kind":"mc","stem":"아침에 일어났을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"안녕히 주무셨어요?","correct":true},{"t":"잘 잤어?","mis":"K1-1-u5-X01"},{"t":"안녕히 주무세요.","mis":"K1-1-u5-X03"}],"explanation":["아침에 일어났을 때 웃어른께는 「안녕히 주무셨어요?」 하고 인사해요.","「잘 잤어?」는 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🌅"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#4','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C3',1,'ox','auto','웃어른께 인사할 때는 주머니에 손을 넣은 채 고개만 끄덕여도 돼요.',ARRAY['K1-1-u5-X04']::text[],true,'{"seq":4,"concept":"K1-1-u5-C3","difficulty":1,"kind":"ox","stem":"웃어른께 인사할 때는 주머니에 손을 넣은 채 고개만 끄덕여도 돼요.","answer":"X","reason_options":[{"t":"손을 빼고 고개를 숙여 공손히 인사해야 하니까","correct":true},{"t":"인사말만 맞으면 자세는 상관없으니까","mis":"K1-1-u5-X04"}],"mis":"K1-1-u5-X04","explanation":["웃어른께는 손을 빼고 고개 숙여 인사해요.","인사말과 함께 자세도 마음을 전해요.","손 빼고, 눈 보고, 고개 숙여요."],"variant_rule":{"alt":[{"stem":"친구에게 인사할 때 딴 곳을 보며 「안녕?」 해도 반가운 마음이 잘 전해져요.","answer":"X","reason_options":[{"t":"친구 얼굴을 보며 밝게 인사해야 마음이 전해지니까","correct":true},{"t":"말만 하면 마음은 저절로 전해지니까","mis":"K1-1-u5-X04"}],"explanation":["눈을 보며 인사해야 반가움이 전해져요.","딴 곳을 보면 친구가 서운할 수 있어요.","얼굴을 보며 밝게 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#5','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C2',2,'mc','auto','「다녀왔습니다.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X03']::text[],true,'{"seq":5,"concept":"K1-1-u5-C2","difficulty":2,"kind":"mc","stem":"「다녀왔습니다.」는 언제 하는 인사말인가요?","options":[{"t":"집에 돌아왔을 때","correct":true},{"t":"집을 나설 때","mis":"K1-1-u5-X02"},{"t":"잠자기 전에","mis":"K1-1-u5-X03"}],"explanation":["「다녀왔습니다.」는 밖에 나갔다가 집에 돌아왔을 때 해요.","집을 나설 때는 「다녀오겠습니다.」예요.","「왔습니다」는 다 돌아왔다는 뜻이에요."],"variant_rule":{"alt":[{"stem":"「다녀오겠습니다.」는 언제 하는 인사말인가요?","options":[{"t":"집을 나설 때","correct":true},{"t":"집에 돌아왔을 때","mis":"K1-1-u5-X02"},{"t":"밥을 먹기 전에","mis":"K1-1-u5-X03"}],"explanation":["「다녀오겠습니다.」는 이제 나갈 때 해요.","돌아왔을 때는 「다녀왔습니다.」예요.","「오겠습니다」는 앞으로 갔다 오겠다는 뜻이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#6','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C1',2,'mc','auto','헤어질 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":6,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"헤어질 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"안녕히 가세요.","correct":true},{"t":"잘 가.","mis":"K1-1-u5-X01"},{"t":"안녕히 주무세요.","mis":"K1-1-u5-X03"}],"explanation":["헤어질 때 웃어른께는 「안녕히 가세요.」 하고 인사해요.","「잘 가.」는 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🚶"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#7','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C2',2,'match','auto','때와 인사말을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u5-C2","difficulty":2,"kind":"match","stem":"때와 인사말을 이으세요.","pairs":[{"l":"밥을 먹기 전에","r":"잘 먹겠습니다."},{"l":"집에 돌아왔을 때","r":"다녀왔습니다."},{"l":"잠자기 전에","r":"안녕히 주무세요."}],"mis":"K1-1-u5-X03","explanation":["먹기 전 「잘 먹겠습니다.」, 돌아와서 「다녀왔습니다.」, 자기 전 「안녕히 주무세요.」","때마다 하는 인사말이 달라요.","하루를 차례대로 떠올려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 때와 인사말을 이으세요.","pairs":[{"l":"아침에 일어났을 때","r":"안녕히 주무셨어요?"},{"l":"집을 나설 때","r":"다녀오겠습니다."},{"l":"밥을 다 먹은 뒤에","r":"잘 먹었습니다."}],"explanation":["일어나서 「안녕히 주무셨어요?」, 나설 때 「다녀오겠습니다.」, 다 먹고 「잘 먹었습니다.」","때마다 하는 인사말이 달라요.","하루를 차례대로 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#8','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C3',2,'mc','auto','친구를 만났을 때 어떤 마음을 담아 인사하면 좋을까요?',ARRAY['K1-1-u5-X04']::text[],true,'{"seq":8,"concept":"K1-1-u5-C3","difficulty":2,"kind":"mc","stem":"친구를 만났을 때 어떤 마음을 담아 인사하면 좋을까요?","options":[{"t":"반가운 마음","correct":true},{"t":"귀찮은 마음","mis":"K1-1-u5-X04"},{"t":"화난 마음","mis":"K1-1-u5-X04"}],"explanation":["반가운 마음을 담으면 친구도 기뻐요.","귀찮거나 화난 마음은 인사로 전하지 않아요.","웃는 얼굴로 반갑게 인사해요."],"asset":{"type":"scene","icon":"😊🧒"},"variant_rule":{"alt":[{"stem":"인사를 하면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 반가운 마음이 전해져 더 가까워져요","correct":true},{"t":"인사를 하면 숙제가 없어져요","mis":"K1-1-u5-X04"},{"t":"인사를 안 해도 마음은 다 알아요","mis":"K1-1-u5-X04"}],"explanation":["인사는 반가운 마음을 전해 사이를 가깝게 해요.","숙제와는 상관없고, 말하지 않으면 마음이 잘 전해지지 않아요.","먼저 반갑게 인사해 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#9','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C1',2,'mc','auto','웃어른께 하는 인사말만 모은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01']::text[],true,'{"seq":9,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"웃어른께 하는 인사말만 모은 것은 어느 것인가요?","options":[{"t":"안녕하세요? · 고맙습니다.","correct":true},{"t":"안녕? · 고맙습니다.","mis":"K1-1-u5-X01"},{"t":"안녕하세요? · 고마워.","mis":"K1-1-u5-X01"}],"explanation":["「안녕하세요?」·「고맙습니다.」는 웃어른께 하는 말이에요.","「안녕?」·「고마워.」는 친구에게 하는 말이에요.","「~요」·「~습니다」로 끝나는지 살펴요."],"variant_rule":{"alt":[{"stem":"친구에게 하는 인사말만 모은 것은 어느 것인가요?","options":[{"t":"안녕? · 미안해.","correct":true},{"t":"안녕? · 죄송합니다.","mis":"K1-1-u5-X01"},{"t":"안녕하세요? · 미안해.","mis":"K1-1-u5-X01"}],"explanation":["「안녕?」·「미안해.」는 친구에게 하는 말이에요.","「죄송합니다.」·「안녕하세요?」는 웃어른께 하는 말이에요.","누구에게 하는 말인지 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_basic#10','kor',1,1,'u5','L01','g1_1_kor_u5_L01_basic','lesson_basic','K1-1-u5-C1',3,'error','auto','하린이가 이웃 할아버지를 만나 손을 흔들며 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#1','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C1',2,'mc','auto','잘못했을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":1,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"잘못했을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"죄송합니다.","correct":true},{"t":"미안해.","mis":"K1-1-u5-X01"},{"t":"축하드립니다.","mis":"K1-1-u5-X03"}],"explanation":["잘못했을 때 웃어른께는 「죄송합니다.」 하고 인사해요.","「미안해.」는 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"💥"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#2','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C2',2,'mc','auto','「잘 먹었습니다.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":2,"concept":"K1-1-u5-C2","difficulty":2,"kind":"mc","stem":"「잘 먹었습니다.」는 언제 하는 인사말인가요?","options":[{"t":"밥을 다 먹은 뒤에","correct":true},{"t":"밥을 먹기 전에","mis":"K1-1-u5-X03"},{"t":"잠자기 전에","mis":"K1-1-u5-X03"}],"explanation":["「잘 먹었습니다.」는 밥을 다 먹은 뒤에 하는 인사말이에요.","다른 때에는 그때에 맞는 인사말이 따로 있어요.","인사말을 들으면 어떤 때인지 장면을 떠올려 봐요."],"variant_rule":{"greet":{"ask":"when","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#3','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C2',3,'mc','auto','하루 동안 한 인사를 때의 차례대로 늘어놓은 것은 어느 것인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X03']::text[],false,'{"seq":3,"concept":"K1-1-u5-C2","difficulty":3,"kind":"mc","stem":"하루 동안 한 인사를 때의 차례대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"안녕히 주무셨어요? → 다녀오겠습니다. → 다녀왔습니다. → 안녕히 주무세요.","correct":true},{"t":"다녀왔습니다. → 다녀오겠습니다. → 안녕히 주무셨어요? → 안녕히 주무세요.","mis":"K1-1-u5-X02"},{"t":"안녕히 주무세요. → 다녀오겠습니다. → 다녀왔습니다. → 안녕히 주무셨어요?","mis":"K1-1-u5-X03"}],"explanation":["아침 → 나설 때 → 돌아와서 → 잠자기 전이에요.","나갈 때와 들어올 때, 아침과 밤 인사를 바꾸면 안 돼요.","하루를 해 뜰 때부터 차례대로 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#4','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C1',3,'mc','auto','같은 「고마움」을 전할 때, 친구와 웃어른께 하는 말을 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":4,"concept":"K1-1-u5-C1","difficulty":3,"kind":"mc","stem":"같은 「고마움」을 전할 때, 친구와 웃어른께 하는 말을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"친구 「고마워.」 — 웃어른 「고맙습니다.」","correct":true},{"t":"친구 「고맙습니다.」 — 웃어른 「고마워.」","mis":"K1-1-u5-X01"},{"t":"친구 「고마워.」 — 웃어른 「축하드립니다.」","mis":"K1-1-u5-X03"}],"explanation":["친구에게 「고마워.」, 웃어른께 「고맙습니다.」","짝을 바꾸거나 다른 때의 인사를 넣으면 안 돼요.","같은 마음도 상대에 따라 말이 달라요."],"variant_rule":{"alt":[{"stem":"같은 「미안함」을 전할 때, 친구와 웃어른께 하는 말을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"친구 「미안해.」 — 웃어른 「죄송합니다.」","correct":true},{"t":"친구 「죄송합니다.」 — 웃어른 「미안해.」","mis":"K1-1-u5-X01"},{"t":"친구 「미안해.」 — 웃어른 「고맙습니다.」","mis":"K1-1-u5-X05"}],"explanation":["친구에게 「미안해.」, 웃어른께 「죄송합니다.」","짝을 바꾸거나 고마움의 말을 넣으면 안 돼요.","같은 마음도 상대에 따라 말이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#5','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C3',3,'mc','auto','선생님께 바르게 인사한 친구는 누구인가요?',ARRAY['K1-1-u5-X04']::text[],false,'{"seq":5,"concept":"K1-1-u5-C3","difficulty":3,"kind":"mc","stem":"선생님께 바르게 인사한 친구는 누구인가요?","options":[{"t":"선생님 눈을 보며 밝게 「안녕하세요?」 하고 고개 숙인 지안","correct":true},{"t":"휴대폰을 보면서 「안녕하세요?」 한 태민","mis":"K1-1-u5-X04"},{"t":"「안녕하세요?」를 작게 중얼거리며 지나간 은솔","mis":"K1-1-u5-X04"}],"explanation":["눈을 보고, 밝은 목소리로, 고개 숙인 지안이 바르게 했어요.","인사말이 맞아도 딴 곳을 보거나 중얼거리면 마음이 전해지지 않아요.","말·눈·목소리·자세를 모두 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#6','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C1',3,'ox','auto','동생에게 잠자기 전 「안녕히 주무세요.」라고 하는 것이 가장 알맞아요.',ARRAY['K1-1-u5-X01']::text[],true,'{"seq":6,"concept":"K1-1-u5-C1","difficulty":3,"kind":"ox","stem":"동생에게 잠자기 전 「안녕히 주무세요.」라고 하는 것이 가장 알맞아요.","answer":"X","reason_options":[{"t":"「안녕히 주무세요.」는 웃어른께 하는 말이고 동생에게는 「잘 자.」가 알맞으니까","correct":true},{"t":"잠자기 전에는 누구에게나 같은 말을 하니까","mis":"K1-1-u5-X01"}],"mis":"K1-1-u5-X01","explanation":["동생에게는 「잘 자.」라고 해요.","「안녕히 주무세요.」는 웃어른께 하는 말이에요.","누구에게 하는지 먼저 살펴요."],"variant_rule":{"alt":[{"stem":"아침에 일어나 할머니께 「잘 잤어?」라고 인사하는 것이 가장 알맞아요.","answer":"X","reason_options":[{"t":"할머니는 웃어른이니 「안녕히 주무셨어요?」가 알맞으니까","correct":true},{"t":"아침에는 누구에게나 「잘 잤어?」라고 하니까","mis":"K1-1-u5-X01"}],"explanation":["할머니께는 「안녕히 주무셨어요?」라고 해요.","「잘 잤어?」는 친구나 동생에게 하는 말이에요.","누구에게 하는지 먼저 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#7','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C2',3,'error','auto','도윤이의 하루 인사예요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#8','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C1',4,'essay','teacher','친구에게 하는 인사와 웃어른께 하는 인사가 어떻게 다른지, 예를 두 가지 들어 말해 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u5-C1","difficulty":4,"kind":"essay","stem":"친구에게 하는 인사와 웃어른께 하는 인사가 어떻게 다른지, 예를 두 가지 들어 말해 보세요.","answer_guide":{"answer":"예: 친구에게는 「안녕?」, 웃어른께는 「안녕하세요?」 / 친구에게는 「고마워.」, 웃어른께는 「고맙습니다.」 — 웃어른께는 더 공손한 말로 해요.","scoring_points":["같은 때에 친구와 웃어른께 하는 인사말을 짝 지어 두 가지 말했는가","웃어른께 하는 말이 공손한 말(~요·~습니다)임을 말했는가","인사말이 때에 맞는가"]},"explanation":["같은 때의 인사말 두 쌍.","웃어른께는 공손한 말.","때에 맞게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#9','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C3',4,'essay','teacher','인사를 하면 좋은 점을 두 가지 쓰고, 웃어른께 인사할 때 바른 자세를 한 가지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u5-C3","difficulty":4,"kind":"essay","stem":"인사를 하면 좋은 점을 두 가지 쓰고, 웃어른께 인사할 때 바른 자세를 한 가지 말해 보세요.","answer_guide":{"answer":"예: 반가운 마음이 전해져요. 서로 더 가까워져요. — 자세: 손을 빼고 고개를 숙여 공손히 인사해요.","scoring_points":["인사하면 좋은 점을 두 가지 썼는가","바른 자세(손 빼기·고개 숙이기·눈 보기)를 말했는가","문장으로 또박또박 썼는가"]},"explanation":["좋은 점 두 가지.","바른 자세 하나.","문장으로 쓰기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L01_challenge#10','kor',1,1,'u5','L01','g1_1_kor_u5_L01_challenge','lesson_challenge','K1-1-u5-C2',4,'mc','auto','은솔이가 아침에 「다녀오겠습니다.」 하고 학교에 갔어요. 집에 돌아와서 은솔이가 할 인사와 엄마가 해 주실 대답을 알맞게 짝 지은 것은 어느 것인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X08']::text[],false,'{"seq":10,"concept":"K1-1-u5-C2","difficulty":4,"kind":"mc","stem":"은솔이가 아침에 「다녀오겠습니다.」 하고 학교에 갔어요. 집에 돌아와서 은솔이가 할 인사와 엄마가 해 주실 대답을 알맞게 짝 지은 것은 어느 것인가요?","options":[{"t":"은솔 「다녀왔습니다.」 — 엄마 「그래, 잘 다녀왔니?」","correct":true},{"t":"은솔 「다녀오겠습니다.」 — 엄마 「그래, 잘 다녀오렴.」","mis":"K1-1-u5-X02"},{"t":"은솔 「다녀왔습니다.」 — 엄마 「잘 먹겠습니다.」","mis":"K1-1-u5-X08"}],"explanation":["돌아와서는 「다녀왔습니다.」, 엄마는 「잘 다녀왔니?」 하고 받아 주세요.","나갈 때 인사를 하거나 엉뚱한 대답을 하면 맞지 않아요.","인사와 대답은 짝을 이뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#1','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C4',1,'mc','auto','도움을 받았을 때 친구에게 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":1,"concept":"K1-1-u5-C4","difficulty":1,"kind":"mc","stem":"도움을 받았을 때 친구에게 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"고마워.","correct":true},{"t":"잘 자.","mis":"K1-1-u5-X03"},{"t":"잘 가.","mis":"K1-1-u5-X03"}],"explanation":["도움을 받았을 때 친구에게는 「고마워.」 하고 인사해요.","다른 인사말은 하는 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🤝"},"variant_rule":{"greet":{"ask":"say","to":"friend","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#2','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C4',1,'mc','auto','짝이 떨어뜨린 지우개를 주워 주었어요. 지우개를 받은 짝이 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X06']::text[],true,'{"seq":2,"concept":"K1-1-u5-C4","difficulty":1,"kind":"mc","stem":"짝이 떨어뜨린 지우개를 주워 주었어요. 지우개를 받은 짝이 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"고마워.","correct":true},{"t":"미안해.","mis":"K1-1-u5-X05"},{"t":"축하해.","mis":"K1-1-u5-X06"}],"explanation":["도움을 받았으니 「고마워.」예요.","「미안해.」는 잘못했을 때, 「축하해.」는 좋은 일이 있을 때 해요.","받았는지, 잘못했는지 먼저 살펴요."],"asset":{"type":"scene","icon":"🧽"},"variant_rule":{"alt":[{"stem":"친구가 무거운 가방 들기를 도와주었어요. 알맞은 인사말은 어느 것인가요?","options":[{"t":"고마워.","correct":true},{"t":"미안해.","mis":"K1-1-u5-X05"},{"t":"잘 자.","mis":"K1-1-u5-X03"}],"explanation":["도움을 받았으니 「고마워.」예요.","잘못한 일도, 잠잘 때도 아니에요.","받았는지, 잘못했는지 먼저 살펴요."],"asset":{"type":"scene","icon":"🎒"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#3','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C4',1,'mc','auto','교실에서 뛰다가 친구와 부딪쳤어요. 먼저 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X06']::text[],true,'{"seq":3,"concept":"K1-1-u5-C4","difficulty":1,"kind":"mc","stem":"교실에서 뛰다가 친구와 부딪쳤어요. 먼저 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"정말 미안해.","correct":true},{"t":"고마워.","mis":"K1-1-u5-X05"},{"t":"축하해.","mis":"K1-1-u5-X06"}],"explanation":["내가 잘못했으니 「미안해.」 하고 사과해요.","「고마워.」·「축하해.」는 이때 하는 말이 아니에요.","잘못했을 때는 먼저 사과해요."],"asset":{"type":"scene","icon":"💥"},"variant_rule":{"alt":[{"stem":"실수로 친구 그림에 물을 쏟았어요. 먼저 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"정말 미안해.","correct":true},{"t":"고마워.","mis":"K1-1-u5-X05"},{"t":"잘 먹겠습니다.","mis":"K1-1-u5-X03"}],"explanation":["내가 잘못했으니 「미안해.」 하고 사과해요.","고마운 일도, 밥 먹을 때도 아니에요.","잘못했을 때는 먼저 사과해요."],"asset":{"type":"scene","icon":"💧"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#4','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C4',1,'mc','auto','좋은 일을 축하할 때 친구에게 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":4,"concept":"K1-1-u5-C4","difficulty":1,"kind":"mc","stem":"좋은 일을 축하할 때 친구에게 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"축하해.","correct":true},{"t":"고마워.","mis":"K1-1-u5-X03"},{"t":"잘 자.","mis":"K1-1-u5-X03"}],"explanation":["좋은 일을 축하할 때 친구에게는 「축하해.」 하고 인사해요.","다른 인사말은 하는 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🏆"},"variant_rule":{"greet":{"ask":"say","to":"friend","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#5','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C5',2,'mc','auto','친구가 「미안해.」 하고 사과했어요. 받아 주는 대답으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X08']::text[],true,'{"seq":5,"concept":"K1-1-u5-C5","difficulty":2,"kind":"mc","stem":"친구가 「미안해.」 하고 사과했어요. 받아 주는 대답으로 알맞은 것은 어느 것인가요?","options":[{"t":"괜찮아. 다음엔 조심하자.","correct":true},{"t":"축하해!","mis":"K1-1-u5-X08"},{"t":"못 들은 척 돌아선다.","mis":"K1-1-u5-X08"}],"explanation":["사과를 받으면 「괜찮아.」 하고 받아 줘요.","엉뚱한 말을 하거나 대답하지 않으면 마음이 이어지지 않아요.","인사는 주고받는 거예요."],"variant_rule":{"alt":[{"stem":"친구가 「생일 축하해!」라고 했어요. 대답으로 알맞은 것은 어느 것인가요?","options":[{"t":"고마워!","correct":true},{"t":"괜찮아.","mis":"K1-1-u5-X08"},{"t":"미안해.","mis":"K1-1-u5-X08"}],"explanation":["축하를 받으면 「고마워!」 하고 대답해요.","「괜찮아.」·「미안해.」는 축하에 맞는 대답이 아니에요.","인사와 대답은 짝을 이뤄요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#6','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C4',2,'mc','auto','할아버지 생신날 할아버지를 뵈었어요. 가장 알맞은 인사말은 어느 것인가요?',ARRAY['K1-1-u5-X16','K1-1-u5-X01']::text[],true,'{"seq":6,"concept":"K1-1-u5-C4","difficulty":2,"kind":"mc","stem":"할아버지 생신날 할아버지를 뵈었어요. 가장 알맞은 인사말은 어느 것인가요?","options":[{"t":"생신 축하드립니다.","correct":true},{"t":"안녕하세요?","mis":"K1-1-u5-X16"},{"t":"생신 축하해!","mis":"K1-1-u5-X01"}],"explanation":["생신이니 「생신 축하드립니다.」가 가장 알맞아요.","「안녕하세요?」도 좋지만 오늘 있는 일(생신)을 놓쳤고, 「축하해!」는 친구에게 하는 말이에요.","누구에게, 무슨 일인지 함께 살펴요."],"asset":{"type":"scene","icon":"🎂👴"},"variant_rule":{"alt":[{"stem":"이웃 아주머니께서 귤을 나눠 주셨어요. 가장 알맞은 인사말은 어느 것인가요?","options":[{"t":"고맙습니다.","correct":true},{"t":"안녕하세요?","mis":"K1-1-u5-X16"},{"t":"고마워.","mis":"K1-1-u5-X01"}],"explanation":["귤을 받았으니 「고맙습니다.」가 가장 알맞아요.","「안녕하세요?」는 받은 일을 놓쳤고, 「고마워.」는 친구에게 하는 말이에요.","누구에게, 무슨 일인지 함께 살펴요."],"asset":{"type":"scene","icon":"🍊"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#7','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C1',2,'mc','auto','도움을 받았을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X05']::text[],true,'{"seq":7,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"도움을 받았을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"고맙습니다.","correct":true},{"t":"고마워.","mis":"K1-1-u5-X01"},{"t":"죄송합니다.","mis":"K1-1-u5-X05"}],"explanation":["도움을 받았을 때 웃어른께는 「고맙습니다.」 하고 인사해요.","「고마워.」는 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🤝"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#8','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C4',2,'ox','auto','친구 집에 초대받아 갔을 때 「초대해 줘서 고마워.」라고 말하면 좋아요.',ARRAY['K1-1-u5-X05']::text[],false,'{"seq":8,"concept":"K1-1-u5-C4","difficulty":2,"kind":"ox","stem":"친구 집에 초대받아 갔을 때 「초대해 줘서 고마워.」라고 말하면 좋아요.","answer":"O","reason_options":[{"t":"초대해 준 마음에 고마움을 전하는 말이니까","correct":true},{"t":"남의 집에 가면 「미안해.」라고 해야 하니까","mis":"K1-1-u5-X05"}],"mis":"K1-1-u5-X05","explanation":["초대받은 것도 고마운 일이에요.","잘못한 일이 없으니 사과할 까닭이 없어요.","고마운 일에는 고마움을 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#9','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C5',2,'match','auto','인사와 대답을 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u5-C5","difficulty":2,"kind":"match","stem":"인사와 대답을 이으세요.","pairs":[{"l":"「축하해!」","r":"「고마워!」"},{"l":"「미안해.」","r":"「괜찮아.」"},{"l":"「안녕하세요?」","r":"「그래, 안녕.」"}],"mis":"K1-1-u5-X08","explanation":["축하 ↔ 고마워, 미안해 ↔ 괜찮아, 안녕하세요 ↔ 그래 안녕.","받은 인사에 맞게 대답해요.","인사와 대답은 짝이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_basic#10','kor',1,1,'u5','L03','g1_1_kor_u5_L03_basic','lesson_basic','K1-1-u5-C4',3,'error','auto','예린이가 역할놀이에서 이웃 아주머니께 선물을 받고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#1','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C4',2,'mc','auto','「죄송합니다.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":1,"concept":"K1-1-u5-C4","difficulty":2,"kind":"mc","stem":"「죄송합니다.」는 언제 하는 인사말인가요?","options":[{"t":"잘못했을 때","correct":true},{"t":"좋은 일을 축하할 때","mis":"K1-1-u5-X03"},{"t":"밥을 먹기 전에","mis":"K1-1-u5-X03"}],"explanation":["「죄송합니다.」는 잘못했을 때 하는 인사말이에요.","다른 때에는 그때에 맞는 인사말이 따로 있어요.","인사말을 들으면 어떤 때인지 장면을 떠올려 봐요."],"variant_rule":{"greet":{"ask":"when","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#2','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C5',2,'mc','auto','역할놀이에서 지킬 약속으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K1-1-u5-X08','K1-1-u5-X04']::text[],false,'{"seq":2,"concept":"K1-1-u5-C5","difficulty":2,"kind":"mc","stem":"역할놀이에서 지킬 약속으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구가 말할 때 끼어들어 먼저 말해요.","correct":true},{"t":"맡은 역할에 맞는 인사말을 해요.","mis":"K1-1-u5-X08"},{"t":"밝은 표정과 바른 자세로 해요.","mis":"K1-1-u5-X04"}],"explanation":["끼어들지 않고 차례를 지켜야 해요.","역할에 맞는 말, 밝은 표정은 지켜야 할 약속이에요.","주고받으려면 차례가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#3','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C4',3,'mc','auto','「고마워.」와 「미안해.」를 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X06']::text[],false,'{"seq":3,"concept":"K1-1-u5-C4","difficulty":3,"kind":"mc","stem":"「고마워.」와 「미안해.」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"물을 쏟은 시우가 짝에게 「미안해.」, 닦아 준 짝에게 「고마워.」","correct":true},{"t":"물을 쏟은 시우가 짝에게 「고마워.」, 닦아 준 짝에게 「미안해.」","mis":"K1-1-u5-X05"},{"t":"물을 쏟은 시우가 짝에게 「축하해.」, 닦아 준 짝에게 「고마워.」","mis":"K1-1-u5-X06"}],"explanation":["잘못한 일에는 「미안해.」, 도움에는 「고마워.」예요.","두 말을 바꾸거나 「축하해.」를 넣으면 안 돼요.","한 장면에 두 가지 마음이 있을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#4','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C4',3,'mc','auto','선생님께서 그림 대회에서 상을 받으셨어요. 가장 알맞은 인사말은 어느 것인가요?',ARRAY['K1-1-u5-X16','K1-1-u5-X01']::text[],false,'{"seq":4,"concept":"K1-1-u5-C4","difficulty":3,"kind":"mc","stem":"선생님께서 그림 대회에서 상을 받으셨어요. 가장 알맞은 인사말은 어느 것인가요?","options":[{"t":"선생님, 축하드립니다.","correct":true},{"t":"선생님, 안녕하세요?","mis":"K1-1-u5-X16"},{"t":"선생님, 축하해!","mis":"K1-1-u5-X01"}],"explanation":["상을 받으셨으니 「축하드립니다.」가 가장 알맞아요.","「안녕하세요?」는 오늘 있는 일을 놓쳤고, 「축하해!」는 친구에게 하는 말이에요.","누구에게, 무슨 일인지 함께 살펴요."],"asset":{"type":"scene","icon":"🏆"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#5','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C5',3,'error','auto','태민이와 지안이의 역할놀이예요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#6','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C5',3,'mc','auto','역할놀이에서 이웃 할머니 역할 친구가 「아이고, 학교 가는구나!」 하고 먼저 말을 걸었어요. 알맞은 대답은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X02']::text[],false,'{"seq":6,"concept":"K1-1-u5-C5","difficulty":3,"kind":"mc","stem":"역할놀이에서 이웃 할머니 역할 친구가 「아이고, 학교 가는구나!」 하고 먼저 말을 걸었어요. 알맞은 대답은 어느 것인가요?","options":[{"t":"「네, 할머니. 안녕하세요?」","correct":true},{"t":"「응, 안녕?」","mis":"K1-1-u5-X01"},{"t":"「다녀왔습니다.」","mis":"K1-1-u5-X02"}],"explanation":["웃어른의 말에 「네」 하고 공손히 인사해요.","「응, 안녕?」은 친구에게 하는 말이고, 「다녀왔습니다.」는 돌아왔을 때 말이에요.","받은 말에 알맞게 대답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#7','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C4',3,'ox','auto','친구 집에서 놀다가 집에 갈 때 친구 엄마께 「잘 가.」라고 인사해요.',ARRAY['K1-1-u5-X07']::text[],false,'{"seq":7,"concept":"K1-1-u5-C4","difficulty":3,"kind":"ox","stem":"친구 집에서 놀다가 집에 갈 때 친구 엄마께 「잘 가.」라고 인사해요.","answer":"X","reason_options":[{"t":"떠나는 사람은 남는 웃어른께 「안녕히 계세요.」라고 해야 하니까","correct":true},{"t":"헤어질 때는 누구에게나 「잘 가.」라고 하니까","mis":"K1-1-u5-X07"}],"mis":"K1-1-u5-X07","explanation":["내가 떠나니 「안녕히 계세요.」예요.","「잘 가.」는 떠나는 친구에게 남는 사람이 하는 말이에요.","누가 떠나는지 먼저 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#8','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C5',4,'essay','teacher','역할놀이 상황을 하나 정해, 두 사람이 주고받는 인사말을 두 줄로 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u5-C5","difficulty":4,"kind":"essay","stem":"역할놀이 상황을 하나 정해, 두 사람이 주고받는 인사말을 두 줄로 써 보세요.","answer_guide":{"answer":"예: (생일) 나: 「생일 축하해!」 / 친구: 「고마워!」","scoring_points":["상황을 하나 정했는가","상황에 알맞은 인사말을 썼는가","받은 인사에 맞는 대답을 썼는가"]},"explanation":["상황 정하기.","알맞은 인사말.","맞는 대답."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#9','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C4',4,'mc','auto','친구 집에서 놀다 나올 때예요. 나와 친구 엄마가 나눌 인사를 알맞게 짝 지은 것은 어느 것인가요?',ARRAY['K1-1-u5-X07']::text[],false,'{"seq":9,"concept":"K1-1-u5-C4","difficulty":4,"kind":"mc","stem":"친구 집에서 놀다 나올 때예요. 나와 친구 엄마가 나눌 인사를 알맞게 짝 지은 것은 어느 것인가요?","options":[{"t":"나 「안녕히 계세요.」 — 친구 엄마 「그래, 잘 가렴.」","correct":true},{"t":"나 「잘 가.」 — 친구 엄마 「안녕히 계세요.」","mis":"K1-1-u5-X07"},{"t":"나 「안녕히 가세요.」 — 친구 엄마 「안녕히 계세요.」","mis":"K1-1-u5-X07"}],"explanation":["떠나는 나는 「안녕히 계세요.」, 남는 친구 엄마는 「잘 가렴.」이에요.","떠나는 사람과 남는 사람의 말을 바꾸면 안 돼요.","누가 떠나고 누가 남는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L03_challenge#10','kor',1,1,'u5','L03','g1_1_kor_u5_L03_challenge','lesson_challenge','K1-1-u5-C4',4,'essay','teacher','친구에게 고마웠던 일과 미안했던 일을 하나씩 떠올려, 그때 할 인사말을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u5-C4","difficulty":4,"kind":"essay","stem":"친구에게 고마웠던 일과 미안했던 일을 하나씩 떠올려, 그때 할 인사말을 써 보세요.","answer_guide":{"answer":"예: 연필을 빌려줬을 때 「고마워.」 / 줄을 서다 밀었을 때 「미안해.」","scoring_points":["고마운 일과 미안한 일을 하나씩 떠올렸는가","고마운 일에 「고마워」, 미안한 일에 「미안해」를 바르게 썼는가","상황과 인사말이 어울리는가"]},"explanation":["고마운 일·미안한 일.","알맞은 인사말.","상황과 어울리게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#1','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C6',1,'mc','auto','동시 「달님도 잘 자요」는 언제 하는 인사를 담았나요?',ARRAY['K1-1-u5-X09']::text[],true,'{"seq":1,"concept":"K1-1-u5-C6","difficulty":1,"kind":"mc","stem":"동시 「달님도 잘 자요」는 언제 하는 인사를 담았나요?","options":[{"t":"잠자기 전 저녁","correct":true},{"t":"아침에 일어났을 때","mis":"K1-1-u5-X09"},{"t":"밥을 먹기 전","mis":"K1-1-u5-X09"}],"explanation":["달이 뜨고 「잘 자」라고 하니 잠자기 전 저녁이에요.","아침이나 밥 먹을 때 인사가 아니에요.","첫 줄 「달이 뜨면」을 다시 봐요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"},"variant_rule":{"alt":[{"stem":"동시 「아침 인사」는 언제 하는 인사를 담았나요?","options":[{"t":"아침에 일어났을 때","correct":true},{"t":"잠자기 전 저녁","mis":"K1-1-u5-X09"},{"t":"밥을 다 먹은 뒤","mis":"K1-1-u5-X09"}],"explanation":["해님이 방긋 웃는 아침 인사예요.","저녁이나 밥 먹은 뒤 인사가 아니에요.","첫 줄 「해님이 방긋」을 다시 봐요."],"asset":{"type":"passage","lines":["창문 너머 해님이 방긋","할머니, 안녕히 주무셨어요?","참새야, 안녕?","나팔꽃아, 안녕?","오늘도 반갑게","인사로 시작해요"],"title":"아침 인사"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#2','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C6',1,'mc','auto','동시 「달님도 잘 자요」에서 인사를 받지 않은 것은 어느 것인가요?',ARRAY['K1-1-u5-X09']::text[],true,'{"seq":2,"concept":"K1-1-u5-C6","difficulty":1,"kind":"mc","stem":"동시 「달님도 잘 자요」에서 인사를 받지 않은 것은 어느 것인가요?","options":[{"t":"참새","correct":true},{"t":"강아지","mis":"K1-1-u5-X09"},{"t":"달님","mis":"K1-1-u5-X09"}],"explanation":["참새는 이 동시에 나오지 않아요.","강아지·달님에게는 「잘 자」라고 인사했어요.","줄마다 누구에게 인사했는지 꼽아 봐요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 동시 「달님도 잘 자요」에서 인사를 받지 않은 것은 어느 것인가요?","options":[{"t":"고양이","correct":true},{"t":"동생","mis":"K1-1-u5-X09"},{"t":"엄마 아빠","mis":"K1-1-u5-X09"}],"explanation":["고양이는 이 동시에 나오지 않아요.","동생·엄마 아빠에게는 인사했어요.","줄마다 누구에게 인사했는지 꼽아 봐요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#3','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C7',1,'mc','auto','동시 「달님도 잘 자요」에서 여러 번 되풀이되는 말은 어느 것인가요?',ARRAY['K1-1-u5-X10']::text[],false,'{"seq":3,"concept":"K1-1-u5-C7","difficulty":1,"kind":"mc","stem":"동시 「달님도 잘 자요」에서 여러 번 되풀이되는 말은 어느 것인가요?","options":[{"t":"잘 자","correct":true},{"t":"달이 뜨면","mis":"K1-1-u5-X10"},{"t":"내일 아침","mis":"K1-1-u5-X10"}],"explanation":["「잘 자」가 세 줄에 되풀이돼요.","「달이 뜨면」·「내일 아침」은 한 번씩 나와요.","되풀이되는 말에 동그라미를 쳐 봐요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#4','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C6',1,'ox','auto','동시 「달님도 잘 자요」에서 엄마 아빠께는 「안녕히 주무세요」라고 인사했어요.',ARRAY['K1-1-u5-X09']::text[],false,'{"seq":4,"concept":"K1-1-u5-C6","difficulty":1,"kind":"ox","stem":"동시 「달님도 잘 자요」에서 엄마 아빠께는 「안녕히 주무세요」라고 인사했어요.","answer":"O","reason_options":[{"t":"둘째 줄에 「엄마 아빠, 안녕히 주무세요」가 나오니까","correct":true},{"t":"엄마 아빠께는 「잘 자」라고 했으니까","mis":"K1-1-u5-X09"}],"mis":"K1-1-u5-X09","explanation":["둘째 줄에서 엄마 아빠께 「안녕히 주무세요」라고 했어요.","「잘 자」는 동생·강아지에게 한 말이에요.","줄마다 누구에게 한 인사인지 살펴요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#5','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C1',2,'mc','auto','동시에서 엄마 아빠께는 「안녕히 주무세요」, 동생에게는 「잘 자」라고 했어요. 인사말이 다른 까닭은 무엇인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X09']::text[],false,'{"seq":5,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"동시에서 엄마 아빠께는 「안녕히 주무세요」, 동생에게는 「잘 자」라고 했어요. 인사말이 다른 까닭은 무엇인가요?","options":[{"t":"엄마 아빠는 웃어른이고 동생은 나보다 어리니까","correct":true},{"t":"엄마 아빠가 먼저 주무시니까","mis":"K1-1-u5-X01"},{"t":"동생이 강아지보다 먼저 나오니까","mis":"K1-1-u5-X09"}],"explanation":["웃어른께는 공손한 말, 동생에게는 편한 말로 인사해요.","자는 차례나 나오는 차례 때문이 아니에요.","상대에 따라 인사말이 달라져요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#6','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C7',2,'mc','auto','「달님도 잘 자요」처럼 틀에 맞게 바꿔 쓴 것은 어느 것인가요?',ARRAY['K1-1-u5-X11']::text[],true,'{"seq":6,"concept":"K1-1-u5-C7","difficulty":2,"kind":"mc","stem":"「달님도 잘 자요」처럼 틀에 맞게 바꿔 쓴 것은 어느 것인가요?","options":[{"t":"창가 화분도 잘 자요","correct":true},{"t":"창가 화분 잘 자요 안녕","mis":"K1-1-u5-X11"},{"t":"창가 화분도 일어나요","mis":"K1-1-u5-X11"}],"explanation":["「(     )도 잘 자요」 틀에서 빈칸만 바꿨어요.","말을 덧붙이거나 「일어나요」로 바꾸면 틀이 깨져요.","빈칸만 바꾸고 나머지는 그대로 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「달님도 잘 자요」처럼 틀에 맞게 바꿔 쓴 것은 어느 것인가요?","options":[{"t":"곰 인형도 잘 자요","correct":true},{"t":"곰 인형이 밥을 먹어요","mis":"K1-1-u5-X11"},{"t":"곰 인형도 잘 자요 또 자요 더 자요","mis":"K1-1-u5-X11"}],"explanation":["빈칸에 「곰 인형」만 넣었어요.","다른 일로 바꾸거나 말을 덧붙이면 틀이 깨져요.","빈칸만 바꾸고 나머지는 그대로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#7','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C7',2,'mc','auto','동시를 리듬을 살려 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X10']::text[],false,'{"seq":7,"concept":"K1-1-u5-C7","difficulty":2,"kind":"mc","stem":"동시를 리듬을 살려 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"되풀이되는 「잘 자」를 같은 가락으로 살려 읽어요","correct":true},{"t":"한 글자씩 뚝뚝 끊어 읽어요","mis":"K1-1-u5-X10"},{"t":"숨 쉬지 않고 아주 빠르게 읽어요","mis":"K1-1-u5-X10"}],"explanation":["되풀이되는 말을 같은 가락으로 읽으면 리듬이 살아나요.","끊어 읽거나 서두르면 리듬이 사라져요.","손뼉을 치며 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#8','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C6',2,'mc','auto','마지막 줄 「내일 아침 또 만나요」에 담긴 마음은 어느 것인가요?',ARRAY['K1-1-u5-X09']::text[],false,'{"seq":8,"concept":"K1-1-u5-C6","difficulty":2,"kind":"mc","stem":"마지막 줄 「내일 아침 또 만나요」에 담긴 마음은 어느 것인가요?","options":[{"t":"내일 다시 반갑게 만나고 싶은 마음","correct":true},{"t":"오늘 만나서 싫었던 마음","mis":"K1-1-u5-X09"},{"t":"빨리 아침밥을 먹고 싶은 마음","mis":"K1-1-u5-X09"}],"explanation":["잘 자라고 인사한 뒤 내일 또 만나자는 반가운 마음이에요.","싫은 마음이나 밥 이야기는 동시에 없어요.","인사말에 담긴 마음을 떠올려요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#9','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C7',2,'mc','auto','짝과 「달님도 잘 자요」를 한 줄씩 번갈아 읽어요. 내가 첫째 줄을 읽었다면 짝이 읽을 줄은 어느 것인가요?',ARRAY['K1-1-u5-X10']::text[],false,'{"seq":9,"concept":"K1-1-u5-C7","difficulty":2,"kind":"mc","stem":"짝과 「달님도 잘 자요」를 한 줄씩 번갈아 읽어요. 내가 첫째 줄을 읽었다면 짝이 읽을 줄은 어느 것인가요?","options":[{"t":"엄마 아빠, 안녕히 주무세요","correct":true},{"t":"내 동생 콩이도 잘 자","mis":"K1-1-u5-X10"},{"t":"하루가 저물고 달이 뜨면","mis":"K1-1-u5-X10"}],"explanation":["번갈아 읽으니 짝은 바로 다음 둘째 줄을 읽어요.","한 줄을 건너뛰거나 내가 읽은 줄을 또 읽으면 안 돼요.","차례를 지키며 한 줄씩 주고받아요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_basic#10','kor',1,1,'u5','L05','g1_1_kor_u5_L05_basic','lesson_basic','K1-1-u5-C6',3,'error','auto','로아가 동시를 듣고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_challenge#1','kor',1,1,'u5','L05','g1_1_kor_u5_L05_challenge','lesson_challenge','K1-1-u5-C6',2,'mc','auto','동시 「아침 인사」에서 할머니께 한 인사말은 어느 것인가요?',ARRAY['K1-1-u5-X09','K1-1-u5-X03']::text[],false,'{"seq":1,"concept":"K1-1-u5-C6","difficulty":2,"kind":"mc","stem":"동시 「아침 인사」에서 할머니께 한 인사말은 어느 것인가요?","options":[{"t":"안녕히 주무셨어요?","correct":true},{"t":"안녕?","mis":"K1-1-u5-X09"},{"t":"안녕히 주무세요","mis":"K1-1-u5-X03"}],"explanation":["둘째 줄에서 할머니께 「안녕히 주무셨어요?」라고 했어요.","「안녕?」은 참새·나팔꽃에게 한 말이고, 「안녕히 주무세요」는 밤 인사예요.","누구에게 한 인사인지 살펴요."],"asset":{"type":"passage","lines":["창문 너머 해님이 방긋","할머니, 안녕히 주무셨어요?","참새야, 안녕?","나팔꽃아, 안녕?","오늘도 반갑게","인사로 시작해요"],"title":"아침 인사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_challenge#2','kor',1,1,'u5','L05','g1_1_kor_u5_L05_challenge','lesson_challenge','K1-1-u5-C7',2,'mc','auto','동시 「아침 인사」에서 되풀이되는 인사말은 어느 것인가요?',ARRAY['K1-1-u5-X10']::text[],false,'{"seq":2,"concept":"K1-1-u5-C7","difficulty":2,"kind":"mc","stem":"동시 「아침 인사」에서 되풀이되는 인사말은 어느 것인가요?","options":[{"t":"안녕?","correct":true},{"t":"방긋","mis":"K1-1-u5-X10"},{"t":"오늘도","mis":"K1-1-u5-X10"}],"explanation":["「안녕?」이 두 줄에 되풀이돼요.","「방긋」·「오늘도」는 한 번씩 나와요.","되풀이되는 말에 동그라미를 쳐 봐요."],"asset":{"type":"passage","lines":["창문 너머 해님이 방긋","할머니, 안녕히 주무셨어요?","참새야, 안녕?","나팔꽃아, 안녕?","오늘도 반갑게","인사로 시작해요"],"title":"아침 인사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_challenge#3','kor',1,1,'u5','L05','g1_1_kor_u5_L05_challenge','lesson_challenge','K1-1-u5-C1',3,'mc','auto','동시 「아침 인사」의 인사말을 바르게 견준 것은 어느 것인가요?',ARRAY['K1-1-u5-X01']::text[],false,'{"seq":3,"concept":"K1-1-u5-C1","difficulty":3,"kind":"mc","stem":"동시 「아침 인사」의 인사말을 바르게 견준 것은 어느 것인가요?","options":[{"t":"할머니께는 공손한 말, 참새·나팔꽃에게는 친구처럼 편한 말","correct":true},{"t":"모두에게 똑같은 말로 인사했어요","mis":"K1-1-u5-X01"},{"t":"참새에게 가장 공손한 말을 했어요","mis":"K1-1-u5-X01"}],"explanation":["할머니께 「안녕히 주무셨어요?」, 참새·나팔꽃에게 「안녕?」이에요.","같은 말이 아니고, 참새에게 공손한 말을 하지 않았어요.","상대에 따라 인사말이 달라져요."],"asset":{"type":"passage","lines":["창문 너머 해님이 방긋","할머니, 안녕히 주무셨어요?","참새야, 안녕?","나팔꽃아, 안녕?","오늘도 반갑게","인사로 시작해요"],"title":"아침 인사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_challenge#4','kor',1,1,'u5','L05','g1_1_kor_u5_L05_challenge','lesson_challenge','K1-1-u5-C6',3,'mc','auto','두 동시 「달님도 잘 자요」와 「아침 인사」의 같은 점은 어느 것인가요?',ARRAY['K1-1-u5-X09']::text[],false,'{"seq":4,"concept":"K1-1-u5-C6","difficulty":3,"kind":"mc","stem":"두 동시 「달님도 잘 자요」와 「아침 인사」의 같은 점은 어느 것인가요?","options":[{"t":"여러 대상에게 차례로 인사해요","correct":true},{"t":"둘 다 아침에 하는 인사예요","mis":"K1-1-u5-X09"},{"t":"둘 다 할머니께 인사해요","mis":"K1-1-u5-X09"}],"explanation":["두 동시 모두 가족·동물·자연에게 차례로 인사해요.","하나는 저녁, 하나는 아침이고 할머니는 「아침 인사」에만 나와요.","두 동시를 나란히 놓고 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
