INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_challenge#6','kor',1,1,'u5','L05','g1_1_kor_u5_L05_challenge','lesson_challenge','K1-1-u5-C7',3,'mc','auto','동시를 낭송할 때 알맞은 모습은 어느 것인가요?',ARRAY['K1-1-u5-X10']::text[],false,'{"seq":6,"concept":"K1-1-u5-C7","difficulty":3,"kind":"mc","stem":"동시를 낭송할 때 알맞은 모습은 어느 것인가요?","options":[{"t":"밝은 목소리로 또박또박, 되풀이되는 말을 살려 읽어요","correct":true},{"t":"글자만 보며 아주 작게 중얼거려요","mis":"K1-1-u5-X10"},{"t":"친구보다 먼저 끝내려고 서둘러 읽어요","mis":"K1-1-u5-X10"}],"explanation":["또박또박, 리듬을 살려 읽어야 듣는 사람도 즐거워요.","중얼거리거나 서두르면 리듬과 뜻이 전해지지 않아요.","손뼉 치며 연습해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_challenge#7','kor',1,1,'u5','L05','g1_1_kor_u5_L05_challenge','lesson_challenge','K1-1-u5-C6',3,'ox','auto','동시 「달님도 잘 자요」에서 인사하는 사람은 강아지예요.',ARRAY['K1-1-u5-X09']::text[],false,'{"seq":7,"concept":"K1-1-u5-C6","difficulty":3,"kind":"ox","stem":"동시 「달님도 잘 자요」에서 인사하는 사람은 강아지예요.","answer":"X","reason_options":[{"t":"「엄마 아빠」「내 동생」이라고 부르는 아이가 인사하니까","correct":true},{"t":"마당 강아지도 동시에 나오니까","mis":"K1-1-u5-X09"}],"mis":"K1-1-u5-X09","explanation":["엄마 아빠와 동생에게 인사하는 아이가 말하는 사람이에요.","강아지는 인사를 받는 쪽이에요.","누가 누구에게 말하는지 살펴요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_challenge#8','kor',1,1,'u5','L05','g1_1_kor_u5_L05_challenge','lesson_challenge','K1-1-u5-C7',4,'essay','teacher','「(     )도 잘 자요」 틀을 써서, 내가 잘 자라고 인사하고 싶은 것을 세 줄로 바꿔 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u5-C7","difficulty":4,"kind":"essay","stem":"「(     )도 잘 자요」 틀을 써서, 내가 잘 자라고 인사하고 싶은 것을 세 줄로 바꿔 써 보세요.","answer_guide":{"answer":"예: 내 이불도 잘 자요 / 어항 물고기도 잘 자요 / 창밖 가로등도 잘 자요","scoring_points":["틀(「(     )도 잘 자요」)을 지켜 세 줄을 썼는가","빈칸에 알맞은 대상을 넣었는가","리듬이 살도록 되풀이되는 말을 살렸는가"]},"explanation":["틀 지키기.","대상 넣기.","리듬 살리기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_challenge#9','kor',1,1,'u5','L05','g1_1_kor_u5_L05_challenge','lesson_challenge','K1-1-u5-C6',4,'essay','teacher','「달님도 잘 자요」를 읽고 떠오른 장면이나 느낌을 말하고, 그렇게 느낀 까닭을 동시에서 찾아 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u5-C6","difficulty":4,"kind":"essay","stem":"「달님도 잘 자요」를 읽고 떠오른 장면이나 느낌을 말하고, 그렇게 느낀 까닭을 동시에서 찾아 말해 보세요.","answer_guide":{"answer":"예: 포근하고 따뜻한 느낌이 들어요 — 가족과 강아지, 달님에게까지 잘 자라고 인사하니까요.","scoring_points":["떠오른 장면이나 느낌을 말했는가","까닭을 동시의 줄에서 찾아 말했는가","문장으로 또박또박 말했는가"]},"explanation":["장면·느낌.","동시에서 까닭 찾기.","문장으로 말하기."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L05_challenge#10','kor',1,1,'u5','L05','g1_1_kor_u5_L05_challenge','lesson_challenge','K1-1-u5-C1',4,'mc','auto','동시 「달님도 잘 자요」에 할머니께 드리는 줄을 하나 더 넣으려고 해요. 가장 알맞은 줄은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],false,'{"seq":10,"concept":"K1-1-u5-C1","difficulty":4,"kind":"mc","stem":"동시 「달님도 잘 자요」에 할머니께 드리는 줄을 하나 더 넣으려고 해요. 가장 알맞은 줄은 어느 것인가요?","options":[{"t":"할머니, 안녕히 주무세요","correct":true},{"t":"할머니도 잘 자","mis":"K1-1-u5-X01"},{"t":"할머니, 다녀오겠습니다","mis":"K1-1-u5-X03"}],"explanation":["할머니는 웃어른이니 「안녕히 주무세요」가 알맞아요.","「잘 자」는 동생에게 하는 말이고, 「다녀오겠습니다」는 나갈 때 인사예요.","상대와 때를 함께 살펴요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#1','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C8',1,'mc','auto','사슴이 멋지다고 자랑한 것은 무엇인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":1,"concept":"K1-1-u5-C8","difficulty":1,"kind":"mc","stem":"사슴이 멋지다고 자랑한 것은 무엇인가요?","options":[{"t":"뿔","correct":true},{"t":"다리","mis":"K1-1-u5-X12"},{"t":"연못","mis":"K1-1-u5-X12"}],"explanation":["사슴은 물에 비친 뿔이 멋지다고 했어요.","다리는 가늘다고 싫어했고, 연못은 사슴이 사는 곳이에요.","이야기 둘째 줄을 다시 봐요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#2','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C9',1,'mc','auto','「악어」는 어떻게 소리 나나요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],true,'{"seq":2,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"「악어」는 어떻게 소리 나나요?","options":[{"t":"[아거]","correct":true},{"t":"[악어]","mis":"K1-1-u5-X13"},{"t":"[악거]","mis":"K1-1-u5-X14"}],"explanation":["「악어」는 소리 내면 [아거] — 받침 ㄱ이 뒤 글자 ㅇ 자리로 넘어가요.","[악어]처럼 글자대로 읽거나 [악거]처럼 받침을 두 번 읽으면 안 돼요.","앞 글자 받침 뒤에 ㅇ이 오면 받침을 뒤로 옮겨 이어 읽어요."],"variant_rule":{"yeon":{"ask":"read","mis":{"keep":"X13","double":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#3','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C9',1,'mc','auto','글자와 소리가 다른 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X15']::text[],true,'{"seq":3,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"글자와 소리가 다른 낱말은 어느 것인가요?","options":[{"t":"걸음","correct":true},{"t":"우산","mis":"K1-1-u5-X15"},{"t":"나무","mis":"K1-1-u5-X15"}],"explanation":["「걸음」은 [거름] 하고 소리 나서 글자와 달라요.","「우산」·「나무」는 글자대로 소리 나요.","앞 글자 받침 뒤에 ㅇ이 오면 소리가 달라져요 — 받침이 없거나 ㅇ 받침이면 그대로예요."],"variant_rule":{"yeon":{"ask":"diff","mis":{"same":"X15"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#4','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C9',1,'ox','auto','「다리미」는 글자와 소리가 같아요.',ARRAY['K1-1-u5-X15']::text[],true,'{"seq":4,"concept":"K1-1-u5-C9","difficulty":1,"kind":"ox","stem":"「다리미」는 글자와 소리가 같아요.","answer":"O","reason_options":[{"t":"받침이 없어서 글자대로 [다리미]로 읽으니까","correct":true},{"t":"모든 낱말은 소리가 바뀌니까","mis":"K1-1-u5-X15"}],"mis":"K1-1-u5-X15","explanation":["받침이 없으니 글자대로 읽어요.","소리가 바뀌는 건 받침 뒤에 ㅇ이 올 때뿐이에요.","받침이 있는지 먼저 봐요."],"variant_rule":{"alt":[{"stem":"「바다」는 글자와 소리가 같아요.","answer":"O","reason_options":[{"t":"받침이 없어서 글자대로 [바다]로 읽으니까","correct":true},{"t":"두 글자 낱말은 모두 소리가 바뀌니까","mis":"K1-1-u5-X15"}],"explanation":["받침이 없으니 글자대로 읽어요.","소리가 바뀌는 건 받침 뒤에 ㅇ이 올 때뿐이에요.","받침이 있는지 먼저 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#5','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C8',2,'mc','auto','사슴이 숲에서 움직일 수 없었던 까닭은 무엇인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":5,"concept":"K1-1-u5-C8","difficulty":2,"kind":"mc","stem":"사슴이 숲에서 움직일 수 없었던 까닭은 무엇인가요?","options":[{"t":"뿔이 나뭇가지에 걸려서","correct":true},{"t":"다리를 다쳐서","mis":"K1-1-u5-X12"},{"t":"잠이 들어서","mis":"K1-1-u5-X12"}],"explanation":["멋진 뿔이 나뭇가지에 걸렸어요.","다리를 다치거나 잠든 일은 이야기에 없어요.","「무슨 일이? 왜?」를 차례대로 짚어요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#6','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C9',2,'mc','auto','「국어」는 어떻게 소리 나나요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],true,'{"seq":6,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"「국어」는 어떻게 소리 나나요?","options":[{"t":"[구거]","correct":true},{"t":"[국어]","mis":"K1-1-u5-X13"},{"t":"[국거]","mis":"K1-1-u5-X14"}],"explanation":["「국어」는 소리 내면 [구거] — 받침 ㄱ이 뒤 글자 ㅇ 자리로 넘어가요.","[국어]처럼 글자대로 읽거나 [국거]처럼 받침을 두 번 읽으면 안 돼요.","앞 글자 받침 뒤에 ㅇ이 오면 받침을 뒤로 옮겨 이어 읽어요."],"variant_rule":{"yeon":{"ask":"read","mis":{"keep":"X13","double":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#7','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C9',2,'mc','auto','글자와 소리가 같은 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X13']::text[],true,'{"seq":7,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"글자와 소리가 같은 낱말은 어느 것인가요?","options":[{"t":"강아지","correct":true},{"t":"먹이","mis":"K1-1-u5-X13"},{"t":"놀이","mis":"K1-1-u5-X13"}],"explanation":["「강아지」는 글자대로 소리 나요.","「먹이」·「놀이」는 받침이 뒤 ㅇ 자리로 넘어가 소리가 달라요.","받침이 없거나 ㅇ 받침이면 글자와 소리가 같아요."],"variant_rule":{"yeon":{"ask":"same","mis":{"diff":"X13"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#8','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C9',2,'mc','auto','이야기에 나온 「사슴은」을 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],true,'{"seq":8,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"이야기에 나온 「사슴은」을 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[사스믄]","correct":true},{"t":"[사슴은]","mis":"K1-1-u5-X13"},{"t":"[사슴믄]","mis":"K1-1-u5-X14"}],"explanation":["받침 ㅁ이 뒤 ㅇ 자리로 넘어가 [사스믄]이에요.","글자대로 읽거나 받침을 두 번 읽으면 안 돼요.","받침을 뒤로 옮겨 이어 읽어요."],"variant_rule":{"alt":[{"stem":"이야기에 나온 「뿔을」을 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[뿌를]","correct":true},{"t":"[뿔을]","mis":"K1-1-u5-X13"},{"t":"[뿔를]","mis":"K1-1-u5-X14"}],"explanation":["받침 ㄹ이 뒤 ㅇ 자리로 넘어가 [뿌를]이에요.","글자대로 읽거나 받침을 두 번 읽으면 안 돼요.","받침을 뒤로 옮겨 이어 읽어요."]},{"stem":"이야기에 나온 「물에」를 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[무레]","correct":true},{"t":"[물에]","mis":"K1-1-u5-X13"},{"t":"[물레]","mis":"K1-1-u5-X14"}],"explanation":["받침 ㄹ이 뒤 ㅇ 자리로 넘어가 [무레]예요.","글자대로 읽거나 받침을 두 번 읽으면 안 돼요.","받침을 뒤로 옮겨 이어 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#9','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C9',2,'match','auto','낱말과 소리를 이으세요.','{}'::text[],true,'{"seq":9,"concept":"K1-1-u5-C9","difficulty":2,"kind":"match","stem":"낱말과 소리를 이으세요.","pairs":[{"l":"먹이","r":"[머기]"},{"l":"얼음","r":"[어름]"},{"l":"웃음","r":"[우슴]"}],"mis":"K1-1-u5-X13","explanation":["먹이 [머기], 얼음 [어름], 웃음 [우슴].","받침이 뒤 ㅇ 자리로 넘어가요.","받침을 옮겨 이어 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 소리를 이으세요.","pairs":[{"l":"음악","r":"[으막]"},{"l":"낙엽","r":"[나겹]"},{"l":"연어","r":"[여너]"}],"explanation":["음악 [으막], 낙엽 [나겹], 연어 [여너].","받침이 뒤 ㅇ 자리로 넘어가요.","받침을 옮겨 이어 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_basic#10','kor',1,1,'u5','L07','g1_1_kor_u5_L07_basic','lesson_basic','K1-1-u5-C9',3,'mc','auto','「사슴은 뿔을 보며 웃었어요.」에서 글자와 소리가 다른 낱말을 모두 고른 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X15']::text[],false,'{"seq":10,"concept":"K1-1-u5-C9","difficulty":3,"kind":"mc","stem":"「사슴은 뿔을 보며 웃었어요.」에서 글자와 소리가 다른 낱말을 모두 고른 것은 어느 것인가요?","options":[{"t":"사슴은 · 뿔을 · 웃었어요","correct":true},{"t":"사슴은 · 뿔을","mis":"K1-1-u5-X13"},{"t":"보며 · 웃었어요","mis":"K1-1-u5-X15"}],"explanation":["사슴은 [사스믄], 뿔을 [뿌를], 웃었어요 [우서써요]예요.","하나를 빠뜨리거나, 받침 없는 「보며」를 넣으면 안 돼요.","낱말마다 받침 뒤에 ㅇ이 오는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#1','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C9',2,'mc','auto','「목요일」은 어떻게 소리 나나요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],true,'{"seq":1,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"「목요일」은 어떻게 소리 나나요?","options":[{"t":"[모교일]","correct":true},{"t":"[목요일]","mis":"K1-1-u5-X13"},{"t":"[목교일]","mis":"K1-1-u5-X14"}],"explanation":["「목요일」은 소리 내면 [모교일] — 받침 ㄱ이 뒤 글자 ㅇ 자리로 넘어가요.","[목요일]처럼 글자대로 읽거나 [목교일]처럼 받침을 두 번 읽으면 안 돼요.","앞 글자 받침 뒤에 ㅇ이 오면 받침을 뒤로 옮겨 이어 읽어요."],"variant_rule":{"yeon":{"ask":"read","mis":{"keep":"X13","double":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#2','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C8',2,'mc','auto','사슴이 처음에 싫어했던 것은 무엇인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":2,"concept":"K1-1-u5-C8","difficulty":2,"kind":"mc","stem":"사슴이 처음에 싫어했던 것은 무엇인가요?","options":[{"t":"가느다란 다리","correct":true},{"t":"멋진 뿔","mis":"K1-1-u5-X12"},{"t":"넓은 숲","mis":"K1-1-u5-X12"}],"explanation":["사슴은 다리가 너무 가늘다고 얼굴을 찡그렸어요.","뿔은 자랑했고, 숲을 싫어한 일은 없어요.","이야기 셋째 줄을 다시 봐요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#3','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C8',3,'mc','auto','사슴이 마지막에 「다리 덕분에 살았구나.」라고 말한 까닭은 무엇인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":3,"concept":"K1-1-u5-C8","difficulty":3,"kind":"mc","stem":"사슴이 마지막에 「다리 덕분에 살았구나.」라고 말한 까닭은 무엇인가요?","options":[{"t":"싫어하던 다리로 빨리 달려 사자에게서 달아났으니까","correct":true},{"t":"멋진 뿔이 사자를 쫓아냈으니까","mis":"K1-1-u5-X12"},{"t":"다리를 다쳐 쉴 수 있었으니까","mis":"K1-1-u5-X12"}],"explanation":["긴 다리로 쌩쌩 달려 사자에게서 달아났어요.","뿔은 오히려 나뭇가지에 걸렸고, 다친 일은 없어요.","일어난 일과 까닭을 이어 봐요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#4','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C9',3,'mc','auto','글자와 소리가 같은 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X13']::text[],true,'{"seq":4,"concept":"K1-1-u5-C9","difficulty":3,"kind":"mc","stem":"글자와 소리가 같은 낱말은 어느 것인가요?","options":[{"t":"고양이","correct":true},{"t":"울음","mis":"K1-1-u5-X13"},{"t":"월요일","mis":"K1-1-u5-X13"}],"explanation":["「고양이」는 글자대로 소리 나요.","「울음」·「월요일」은 받침이 뒤 ㅇ 자리로 넘어가 소리가 달라요.","받침이 없거나 ㅇ 받침이면 글자와 소리가 같아요."],"variant_rule":{"yeon":{"ask":"same","mis":{"diff":"X13"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#5','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C9',3,'error','auto','시우가 소리 나는 대로 적었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#6','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C9',3,'mc','auto','받침이 뒤로 넘어가 소리가 달라지는 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u5-X15']::text[],false,'{"seq":6,"concept":"K1-1-u5-C9","difficulty":3,"kind":"mc","stem":"받침이 뒤로 넘어가 소리가 달라지는 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"앞 글자 받침 뒤에 ㅇ으로 시작하는 글자가 와서","correct":true},{"t":"낱말이 세 글자라서","mis":"K1-1-u5-X15"},{"t":"뒤 글자에 받침이 있어서","mis":"K1-1-u5-X15"}],"explanation":["앞 받침 + 뒤 ㅇ이면 받침이 그 자리로 넘어가요.","글자 수나 뒤 글자 받침과는 상관없어요.","두 가지가 다 맞는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#7','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C9',3,'ox','auto','「강아지」도 앞 글자에 받침이 있고 뒤에 ㅇ이 오니까 [가아지]로 소리 나요.',ARRAY['K1-1-u5-X15']::text[],true,'{"seq":7,"concept":"K1-1-u5-C9","difficulty":3,"kind":"ox","stem":"「강아지」도 앞 글자에 받침이 있고 뒤에 ㅇ이 오니까 [가아지]로 소리 나요.","answer":"X","reason_options":[{"t":"ㅇ 받침은 뒤로 넘어가지 않아 글자대로 [강아지]로 읽으니까","correct":true},{"t":"받침이 있고 뒤에 ㅇ이 오면 언제나 넘어가니까","mis":"K1-1-u5-X15"}],"mis":"K1-1-u5-X15","explanation":["ㅇ 받침은 넘어가지 않아요 — [강아지].","ㅇ 받침만은 그대로 읽어요.","받침이 무엇인지도 살펴요."],"variant_rule":{"alt":[{"stem":"「고양이」도 앞 글자에 받침이 있고 뒤에 ㅇ이 오니까 [고야이]로 소리 나요.","answer":"X","reason_options":[{"t":"ㅇ 받침은 뒤로 넘어가지 않아 글자대로 [고양이]로 읽으니까","correct":true},{"t":"받침이 있고 뒤에 ㅇ이 오면 언제나 넘어가니까","mis":"K1-1-u5-X15"}],"explanation":["ㅇ 받침은 넘어가지 않아요 — [고양이].","ㅇ 받침만은 그대로 읽어요.","받침이 무엇인지도 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#8','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C9',4,'essay','teacher','글자와 소리가 다른 낱말 두 개와 같은 낱말 두 개를 골라 두 갈래로 나누고, 나눈 까닭을 말해 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u5-C9","difficulty":4,"kind":"essay","stem":"글자와 소리가 다른 낱말 두 개와 같은 낱말 두 개를 골라 두 갈래로 나누고, 나눈 까닭을 말해 보세요.","answer_guide":{"answer":"예: 다른 낱말 — 악어 [아거], 얼음 [어름] / 같은 낱말 — 우산, 강아지 — 앞 받침 뒤에 ㅇ이 오면 받침이 넘어가 소리가 달라지고, 받침이 없거나 ㅇ 받침이면 그대로예요.","scoring_points":["글자와 소리가 다른 낱말 두 개를 바르게 골랐는가","같은 낱말 두 개를 바르게 골랐는가","「앞 받침 + 뒤 ㅇ」 까닭을 말했는가"]},"explanation":["다른 낱말 두 개.","같은 낱말 두 개.","나눈 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#9','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C8',4,'essay','teacher','「사슴과 뿔」을 읽고, 이야기 내용과 이어서 사슴에게 해 주고 싶은 말을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u5-C8","difficulty":4,"kind":"essay","stem":"「사슴과 뿔」을 읽고, 이야기 내용과 이어서 사슴에게 해 주고 싶은 말을 써 보세요.","answer_guide":{"answer":"예: 「사슴아, 네 다리는 가늘지만 빨리 달릴 수 있는 멋진 다리야. 뿔만 자랑하지 말고 다리도 아껴 줘.」","scoring_points":["이야기에서 일어난 일(뿔이 걸림·다리로 달아남)과 이어서 썼는가","사슴의 마음이 바뀐 까닭을 알고 썼는가","사슴에게 말하듯 문장으로 썼는가"]},"explanation":["일어난 일과 잇기.","마음이 바뀐 까닭.","말하듯 쓰기."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L07_challenge#10','kor',1,1,'u5','L07','g1_1_kor_u5_L07_challenge','lesson_challenge','K1-1-u5-C9',4,'mc','auto','「바람이 불어요.」를 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],true,'{"seq":10,"concept":"K1-1-u5-C9","difficulty":4,"kind":"mc","stem":"「바람이 불어요.」를 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[바라미 부러요]","correct":true},{"t":"[바람이 부러요]","mis":"K1-1-u5-X13"},{"t":"[바라미 불러요]","mis":"K1-1-u5-X14"}],"explanation":["바람이 [바라미], 불어요 [부러요] — 두 곳 모두 받침이 넘어가요.","한 곳만 넘기거나 받침을 두 번 읽으면 안 돼요.","문장 안 낱말마다 살펴요."],"variant_rule":{"alt":[{"stem":"「얼음이 녹아요.」를 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[어르미 노가요]","correct":true},{"t":"[얼음이 노가요]","mis":"K1-1-u5-X13"},{"t":"[어르미 녹가요]","mis":"K1-1-u5-X14"}],"explanation":["얼음이 [어르미], 녹아요 [노가요] — 두 곳 모두 받침이 넘어가요.","한 곳만 넘기거나 받침을 두 번 읽으면 안 돼요.","문장 안 낱말마다 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#1','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C10',1,'mc','auto','친구가 다른 학교로 전학을 가요. 알맞은 인사말은 어느 것인가요?',ARRAY['K1-1-u5-X06','K1-1-u5-X05']::text[],false,'{"seq":1,"concept":"K1-1-u5-C10","difficulty":1,"kind":"mc","stem":"친구가 다른 학교로 전학을 가요. 알맞은 인사말은 어느 것인가요?","options":[{"t":"잘 가, 가서도 잘 지내.","correct":true},{"t":"축하해.","mis":"K1-1-u5-X06"},{"t":"미안해.","mis":"K1-1-u5-X05"}],"explanation":["헤어지는 친구에게 따뜻한 작별 인사를 해요.","축하하거나 사과할 일이 아니에요.","친구 마음을 떠올려 봐요."],"asset":{"type":"scene","icon":"🧳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#2','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C10',1,'mc','auto','감기에 걸려 아픈 친구에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X06','K1-1-u5-X03']::text[],false,'{"seq":2,"concept":"K1-1-u5-C10","difficulty":1,"kind":"mc","stem":"감기에 걸려 아픈 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"빨리 나아서 함께 놀자.","correct":true},{"t":"축하해.","mis":"K1-1-u5-X06"},{"t":"잘 먹겠습니다.","mis":"K1-1-u5-X03"}],"explanation":["아픈 친구에게는 걱정하고 위로하는 말을 해요.","축하할 일도, 밥 먹을 때도 아니에요.","친구가 기쁠지 속상할지 떠올려요."],"asset":{"type":"scene","icon":"🤒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#3','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C4',1,'mc','auto','좋은 일을 축하할 때 친구에게 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":3,"concept":"K1-1-u5-C4","difficulty":1,"kind":"mc","stem":"좋은 일을 축하할 때 친구에게 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"축하해.","correct":true},{"t":"미안해.","mis":"K1-1-u5-X03"},{"t":"잘 가.","mis":"K1-1-u5-X03"}],"explanation":["좋은 일을 축하할 때 친구에게는 「축하해.」 하고 인사해요.","다른 인사말은 하는 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🏆"},"variant_rule":{"greet":{"ask":"say","to":"friend","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#4','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C10',1,'mc','auto','할머니와 전화를 끊을 때 하는 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X03']::text[],false,'{"seq":4,"concept":"K1-1-u5-C10","difficulty":1,"kind":"mc","stem":"할머니와 전화를 끊을 때 하는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"할머니, 이만 끊을게요. 안녕히 계세요.","correct":true},{"t":"다녀왔습니다.","mis":"K1-1-u5-X03"},{"t":"잘 먹었습니다.","mis":"K1-1-u5-X03"}],"explanation":["전화를 끊을 때도 인사를 하고 끊어요.","다른 두 말은 때가 달라요.","전화도 만남처럼 인사로 끝내요."],"asset":{"type":"scene","icon":"📞"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#5','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C1',2,'mc','auto','잠자기 전에 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":5,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"잠자기 전에 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"안녕히 주무세요.","correct":true},{"t":"잘 자.","mis":"K1-1-u5-X01"},{"t":"잘 먹었습니다.","mis":"K1-1-u5-X03"}],"explanation":["잠자기 전에 웃어른께는 「안녕히 주무세요.」 하고 인사해요.","「잘 자.」는 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🌙"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#6','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C4',2,'mc','auto','「축하해.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":6,"concept":"K1-1-u5-C4","difficulty":2,"kind":"mc","stem":"「축하해.」는 언제 하는 인사말인가요?","options":[{"t":"좋은 일을 축하할 때","correct":true},{"t":"잘못했을 때","mis":"K1-1-u5-X03"},{"t":"잠자기 전에","mis":"K1-1-u5-X03"}],"explanation":["「축하해.」는 좋은 일을 축하할 때 하는 인사말이에요.","다른 때에는 그때에 맞는 인사말이 따로 있어요.","인사말을 들으면 어떤 때인지 장면을 떠올려 봐요."],"variant_rule":{"greet":{"ask":"when","to":"friend","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#7','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C10',2,'mc','auto','인사 놀이 방법의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X08']::text[],false,'{"seq":7,"concept":"K1-1-u5-C10","difficulty":2,"kind":"mc","stem":"인사 놀이 방법의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"상황 말하기 → 「저요!」 외치기 → 알맞은 인사말 하기","correct":true},{"t":"「저요!」 외치기 → 상황 말하기 → 인사말 하기","mis":"K1-1-u5-X08"},{"t":"인사말 하기 → 상황 말하기 → 「저요!」 외치기","mis":"K1-1-u5-X08"}],"explanation":["상황을 듣고 → 「저요!」 → 인사말 차례예요.","상황을 듣기 전에 외치거나 말하면 놀이가 안 돼요.","차례를 지켜야 즐거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#8','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C10',2,'match','auto','상황과 인사말을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u5-C10","difficulty":2,"kind":"match","stem":"상황과 인사말을 이으세요.","pairs":[{"l":"졸업하는 언니를 볼 때","r":"졸업 축하해."},{"l":"넘어진 친구를 볼 때","r":"괜찮아? 많이 아프지?"},{"l":"놀이터에서 친구와 헤어질 때","r":"안녕, 내일 보자."}],"mis":"K1-1-u5-X06","explanation":["졸업에는 축하, 다친 친구에게는 위로, 헤어질 때는 작별 인사예요.","기쁜 일과 속상한 일을 거꾸로 하면 안 돼요.","상황마다 친구 마음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#9','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C10',2,'ox','auto','친구가 넘어져 무릎을 다쳤을 때 「축하해.」라고 말해요.',ARRAY['K1-1-u5-X06']::text[],false,'{"seq":9,"concept":"K1-1-u5-C10","difficulty":2,"kind":"ox","stem":"친구가 넘어져 무릎을 다쳤을 때 「축하해.」라고 말해요.","answer":"X","reason_options":[{"t":"다친 친구에게는 걱정하고 위로하는 말을 해야 하니까","correct":true},{"t":"큰 소리로 말하면 어떤 인사도 괜찮으니까","mis":"K1-1-u5-X06"}],"mis":"K1-1-u5-X06","explanation":["다친 친구에게는 「괜찮아?」 하고 위로해요.","기쁜 일이 아니니 축하하지 않아요.","친구 얼굴을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_basic#10','kor',1,1,'u5','L09','g1_1_kor_u5_L09_basic','lesson_basic','K1-1-u5-C10',3,'error','auto','인사 놀이에서 나온 대답이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_challenge#1','kor',1,1,'u5','L09','g1_1_kor_u5_L09_challenge','lesson_challenge','K1-1-u5-C4',2,'mc','auto','「고맙습니다.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X03']::text[],true,'{"seq":1,"concept":"K1-1-u5-C4","difficulty":2,"kind":"mc","stem":"「고맙습니다.」는 언제 하는 인사말인가요?","options":[{"t":"도움을 받았을 때","correct":true},{"t":"잘못했을 때","mis":"K1-1-u5-X05"},{"t":"잠자기 전에","mis":"K1-1-u5-X03"}],"explanation":["「고맙습니다.」는 도움을 받았을 때 하는 인사말이에요.","다른 때에는 그때에 맞는 인사말이 따로 있어요.","인사말을 들으면 어떤 때인지 장면을 떠올려 봐요."],"variant_rule":{"greet":{"ask":"when","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_challenge#2','kor',1,1,'u5','L09','g1_1_kor_u5_L09_challenge','lesson_challenge','K1-1-u5-C10',2,'mc','auto','친구에게 실수를 했을 때 마음을 잘 전하는 말은 어느 것인가요?',ARRAY['K1-1-u5-X08','K1-1-u5-X05']::text[],false,'{"seq":2,"concept":"K1-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구에게 실수를 했을 때 마음을 잘 전하는 말은 어느 것인가요?","options":[{"t":"미안해. 다음부터 조심할게.","correct":true},{"t":"괜찮아, 별거 아니야.","mis":"K1-1-u5-X08"},{"t":"고마워.","mis":"K1-1-u5-X05"}],"explanation":["사과하고 앞으로 조심하겠다고 말하면 마음이 잘 전해져요.","「괜찮아」는 사과를 받은 사람이 하는 말이에요.","내가 잘못했으면 먼저 사과해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_challenge#3','kor',1,1,'u5','L09','g1_1_kor_u5_L09_challenge','lesson_challenge','K1-1-u5-C10',3,'mc','auto','친구가 상을 받았는데 나는 받지 못해 속상해요. 그래도 친구에게 할 인사로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X06','K1-1-u5-X05']::text[],false,'{"seq":3,"concept":"K1-1-u5-C10","difficulty":3,"kind":"mc","stem":"친구가 상을 받았는데 나는 받지 못해 속상해요. 그래도 친구에게 할 인사로 알맞은 것은 어느 것인가요?","options":[{"t":"축하해. 정말 잘했다.","correct":true},{"t":"나는 왜 못 받았지.","mis":"K1-1-u5-X06"},{"t":"미안해.","mis":"K1-1-u5-X05"}],"explanation":["내 마음이 속상해도 친구의 기쁜 일은 축하해요.","내 이야기만 하거나 사과할 일이 아니에요.","친구 마음을 먼저 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_challenge#4','kor',1,1,'u5','L09','g1_1_kor_u5_L09_challenge','lesson_challenge','K1-1-u5-C10',3,'mc','auto','할머니께서 감기에 걸리셨어요. 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X06']::text[],false,'{"seq":4,"concept":"K1-1-u5-C10","difficulty":3,"kind":"mc","stem":"할머니께서 감기에 걸리셨어요. 알맞은 말은 어느 것인가요?","options":[{"t":"할머니, 얼른 나으세요.","correct":true},{"t":"할머니, 안녕?","mis":"K1-1-u5-X01"},{"t":"할머니, 축하드립니다.","mis":"K1-1-u5-X06"}],"explanation":["아프신 할머니께 공손하게 위로해요.","「안녕?」은 친구에게 하는 말이고, 축하할 일이 아니에요.","상대와 상황을 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
