INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_challenge#6','kor',1,1,'u5','L09','g1_1_kor_u5_L09_challenge','lesson_challenge','K1-1-u5-C1',3,'mc','auto','잘못했을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":6,"concept":"K1-1-u5-C1","difficulty":3,"kind":"mc","stem":"잘못했을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"죄송합니다.","correct":true},{"t":"미안해.","mis":"K1-1-u5-X01"},{"t":"안녕히 주무세요.","mis":"K1-1-u5-X03"}],"explanation":["잘못했을 때 웃어른께는 「죄송합니다.」 하고 인사해요.","「미안해.」는 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"💥"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_challenge#7','kor',1,1,'u5','L09','g1_1_kor_u5_L09_challenge','lesson_challenge','K1-1-u5-C10',3,'mc','auto','인사 놀이에서 지킬 점으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X08','K1-1-u5-X04']::text[],false,'{"seq":7,"concept":"K1-1-u5-C10","difficulty":3,"kind":"mc","stem":"인사 놀이에서 지킬 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"차례를 지키고 친구가 말할 때 끼어들지 않아요","correct":true},{"t":"먼저 맞히려고 친구 말을 끊어요","mis":"K1-1-u5-X08"},{"t":"틀린 친구를 놀려요","mis":"K1-1-u5-X04"}],"explanation":["차례를 지켜야 모두 즐겁게 놀 수 있어요.","말을 끊거나 놀리면 마음이 상해요.","친구 말을 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_challenge#8','kor',1,1,'u5','L09','g1_1_kor_u5_L09_challenge','lesson_challenge','K1-1-u5-C10',4,'essay','teacher','오늘 만날 사람 두 명을 정해, 언제 어떤 인사말을 할지 계획을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u5-C10","difficulty":4,"kind":"essay","stem":"오늘 만날 사람 두 명을 정해, 언제 어떤 인사말을 할지 계획을 써 보세요.","answer_guide":{"answer":"예: 아침에 경비 아저씨께 「안녕하세요?」 / 점심에 짝에게 「같이 놀자, 고마워.」","scoring_points":["만날 사람 두 명을 정했는가","언제 인사할지 썼는가","상대와 때에 알맞은 인사말을 썼는가"]},"explanation":["만날 사람 두 명.","언제.","알맞은 인사말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_challenge#9','kor',1,1,'u5','L09','g1_1_kor_u5_L09_challenge','lesson_challenge','K1-1-u5-C10',4,'mc','auto','하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X05']::text[],false,'{"seq":9,"concept":"K1-1-u5-C10","difficulty":4,"kind":"mc","stem":"하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?","options":[{"t":"아침에 할아버지께 「안녕히 주무셨어요?」, 친구에게 도움을 받고 「고마워.」, 저녁밥 먹기 전 「잘 먹겠습니다.」","correct":true},{"t":"아침에 할아버지께 「잘 잤어?」, 친구에게 도움을 받고 「고마워.」, 저녁밥 먹기 전 「잘 먹겠습니다.」","mis":"K1-1-u5-X01"},{"t":"아침에 할아버지께 「안녕히 주무셨어요?」, 친구에게 도움을 받고 「미안해.」, 저녁밥 먹기 전 「잘 먹겠습니다.」","mis":"K1-1-u5-X05"}],"explanation":["할아버지께 공손한 아침 인사, 도움에 고마움, 먹기 전 인사 — 모두 알맞아요.","할아버지께 「잘 잤어?」나 도움에 「미안해.」는 맞지 않아요.","한 줄씩 상대와 상황을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_L09_challenge#10','kor',1,1,'u5','L09','g1_1_kor_u5_L09_challenge','lesson_challenge','K1-1-u5-C5',4,'essay','teacher','친구가 사과했을 때와 축하해 주었을 때, 각각 어떤 대답을 하면 좋을지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u5-C5","difficulty":4,"kind":"essay","stem":"친구가 사과했을 때와 축하해 주었을 때, 각각 어떤 대답을 하면 좋을지 써 보세요.","answer_guide":{"answer":"예: 사과했을 때 「괜찮아. 다음엔 조심하자.」 / 축하해 주었을 때 「고마워!」","scoring_points":["사과에 알맞은 대답을 썼는가","축하에 알맞은 대답을 썼는가","대답에 마음이 담겼는가"]},"explanation":["사과에 대한 대답.","축하에 대한 대답.","마음 담기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#1','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C1',1,'mc','auto','만났을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":1,"concept":"K1-1-u5-C1","difficulty":1,"kind":"mc","stem":"만났을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"안녕하세요?","correct":true},{"t":"안녕?","mis":"K1-1-u5-X01"},{"t":"고맙습니다.","mis":"K1-1-u5-X03"}],"explanation":["만났을 때 웃어른께는 「안녕하세요?」 하고 인사해요.","「안녕?」은 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"👋"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#2','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C2',1,'mc','auto','집을 나설 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X03']::text[],true,'{"seq":2,"concept":"K1-1-u5-C2","difficulty":1,"kind":"mc","stem":"집을 나설 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"다녀오겠습니다.","correct":true},{"t":"다녀왔습니다.","mis":"K1-1-u5-X02"},{"t":"안녕히 주무세요.","mis":"K1-1-u5-X03"}],"explanation":["집을 나설 때 웃어른께는 「다녀오겠습니다.」 하고 인사해요.","다른 인사말은 하는 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🎒"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#3','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C3',1,'ox','auto','웃어른께는 손을 빼고 고개를 숙여 공손히 인사해요.',ARRAY['K1-1-u5-X04']::text[],false,'{"seq":3,"concept":"K1-1-u5-C3","difficulty":1,"kind":"ox","stem":"웃어른께는 손을 빼고 고개를 숙여 공손히 인사해요.","answer":"O","reason_options":[{"t":"공손한 자세가 공경하는 마음을 전하니까","correct":true},{"t":"인사말만 하면 자세는 상관없으니까","mis":"K1-1-u5-X04"}],"mis":"K1-1-u5-X04","explanation":["손을 빼고 고개를 숙이는 것이 바른 자세예요.","자세도 마음을 전해요.","손 빼고, 눈 보고, 밝은 목소리로 인사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#4','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C4',1,'mc','auto','짝이 떨어뜨린 연필을 주워 주었어요. 연필을 받은 짝이 할 말은 어느 것인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X06']::text[],false,'{"seq":4,"concept":"K1-1-u5-C4","difficulty":1,"kind":"mc","stem":"짝이 떨어뜨린 연필을 주워 주었어요. 연필을 받은 짝이 할 말은 어느 것인가요?","options":[{"t":"고마워.","correct":true},{"t":"미안해.","mis":"K1-1-u5-X05"},{"t":"축하해.","mis":"K1-1-u5-X06"}],"explanation":["도움을 받았으니 「고마워.」예요.","다른 두 말은 이 상황에 맞지 않아요.","받았는지, 잘못했는지, 기쁜 일인지 살펴요."],"asset":{"type":"scene","icon":"✏️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#5','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C6',1,'mc','auto','「달님도 잘 자요」에서 동생에게 한 인사말은 어느 것인가요?',ARRAY['K1-1-u5-X09']::text[],false,'{"seq":5,"concept":"K1-1-u5-C6","difficulty":1,"kind":"mc","stem":"「달님도 잘 자요」에서 동생에게 한 인사말은 어느 것인가요?","options":[{"t":"잘 자","correct":true},{"t":"안녕히 주무세요","mis":"K1-1-u5-X09"},{"t":"안녕?","mis":"K1-1-u5-X09"}],"explanation":["동생에게는 「잘 자」라고 했어요.","다른 두 보기는 동시에 나오지 않거나 다른 줄이에요.","줄마다 누구에게, 무엇이라고 했는지 꼽아요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#6','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C8',1,'mc','auto','사슴이 멋지다고 자랑한 것은 무엇인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":6,"concept":"K1-1-u5-C8","difficulty":1,"kind":"mc","stem":"사슴이 멋지다고 자랑한 것은 무엇인가요?","options":[{"t":"뿔","correct":true},{"t":"다리","mis":"K1-1-u5-X12"},{"t":"꼬리","mis":"K1-1-u5-X12"}],"explanation":["물에 비친 뿔을 자랑했어요.","다른 두 보기는 이야기에서 일어나지 않은 일이에요.","이야기를 차례대로 떠올려요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#7','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C9',1,'mc','auto','「걸음」은 어떻게 소리 나나요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],true,'{"seq":7,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"「걸음」은 어떻게 소리 나나요?","options":[{"t":"[거름]","correct":true},{"t":"[걸음]","mis":"K1-1-u5-X13"},{"t":"[걸름]","mis":"K1-1-u5-X14"}],"explanation":["「걸음」은 소리 내면 [거름] — 받침 ㄹ이 뒤 글자 ㅇ 자리로 넘어가요.","[걸음]처럼 글자대로 읽거나 [걸름]처럼 받침을 두 번 읽으면 안 돼요.","앞 글자 받침 뒤에 ㅇ이 오면 받침을 뒤로 옮겨 이어 읽어요."],"variant_rule":{"yeon":{"ask":"read","mis":{"keep":"X13","double":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#8','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C9',1,'mc','auto','글자와 소리가 다른 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X15']::text[],true,'{"seq":8,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"글자와 소리가 다른 낱말은 어느 것인가요?","options":[{"t":"악어","correct":true},{"t":"바다","mis":"K1-1-u5-X15"},{"t":"우산","mis":"K1-1-u5-X15"}],"explanation":["「악어」는 [아거] 하고 소리 나서 글자와 달라요.","「바다」·「우산」은 글자대로 소리 나요.","앞 글자 받침 뒤에 ㅇ이 오면 소리가 달라져요 — 받침이 없거나 ㅇ 받침이면 그대로예요."],"variant_rule":{"yeon":{"ask":"diff","mis":{"same":"X15"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#9','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C1',2,'mc','auto','「고맙습니다.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X03']::text[],true,'{"seq":9,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"「고맙습니다.」는 언제 하는 인사말인가요?","options":[{"t":"도움을 받았을 때","correct":true},{"t":"잘못했을 때","mis":"K1-1-u5-X05"},{"t":"잠자기 전에","mis":"K1-1-u5-X03"}],"explanation":["「고맙습니다.」는 도움을 받았을 때 하는 인사말이에요.","다른 때에는 그때에 맞는 인사말이 따로 있어요.","인사말을 들으면 어떤 때인지 장면을 떠올려 봐요."],"variant_rule":{"greet":{"ask":"when","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#10','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C5',2,'mc','auto','친구가 「발을 밟아서 미안해.」라고 했어요. 대답으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X08']::text[],false,'{"seq":10,"concept":"K1-1-u5-C5","difficulty":2,"kind":"mc","stem":"친구가 「발을 밟아서 미안해.」라고 했어요. 대답으로 알맞은 것은 어느 것인가요?","options":[{"t":"괜찮아.","correct":true},{"t":"축하해.","mis":"K1-1-u5-X08"},{"t":"고마워.","mis":"K1-1-u5-X08"}],"explanation":["「발을 밟아서 미안해.」에는 「괜찮아.」 하고 대답해요.","다른 두 말은 받은 인사에 맞지 않아요.","인사와 대답은 짝이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#11','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C7',2,'mc','auto','「달님도 잘 자요」에서 되풀이되는 말은 어느 것인가요?',ARRAY['K1-1-u5-X10']::text[],false,'{"seq":11,"concept":"K1-1-u5-C7","difficulty":2,"kind":"mc","stem":"「달님도 잘 자요」에서 되풀이되는 말은 어느 것인가요?","options":[{"t":"잘 자","correct":true},{"t":"달이 뜨면","mis":"K1-1-u5-X10"},{"t":"또 만나요","mis":"K1-1-u5-X10"}],"explanation":["「잘 자」가 세 줄에 되풀이돼요.","다른 말은 한 번씩 나와요.","되풀이되는 말에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#12','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C9',2,'mc','auto','글자와 소리가 같은 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X13']::text[],true,'{"seq":12,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"글자와 소리가 같은 낱말은 어느 것인가요?","options":[{"t":"다리미","correct":true},{"t":"목요일","mis":"K1-1-u5-X13"},{"t":"길이","mis":"K1-1-u5-X13"}],"explanation":["「다리미」는 글자대로 소리 나요.","「목요일」·「길이」는 받침이 뒤 ㅇ 자리로 넘어가 소리가 달라요.","받침이 없거나 ㅇ 받침이면 글자와 소리가 같아요."],"variant_rule":{"yeon":{"ask":"same","mis":{"diff":"X13"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#13','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C10',2,'mc','auto','친구가 다른 학교로 전학을 가요. 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u5-X06','K1-1-u5-X05']::text[],false,'{"seq":13,"concept":"K1-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 다른 학교로 전학을 가요. 알맞은 말은 어느 것인가요?","options":[{"t":"잘 가, 가서도 잘 지내.","correct":true},{"t":"축하해!","mis":"K1-1-u5-X06"},{"t":"미안해.","mis":"K1-1-u5-X05"}],"explanation":["헤어지는 친구에게 따뜻한 작별 인사를 해요.","다른 두 말은 이 상황과 어울리지 않아요.","친구 마음을 먼저 떠올려요."],"asset":{"type":"scene","icon":"🧳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#14','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C2',2,'mc','auto','아침에 학교에 갈 때 엄마께 하는 인사말은 어느 것인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X03']::text[],false,'{"seq":14,"concept":"K1-1-u5-C2","difficulty":2,"kind":"mc","stem":"아침에 학교에 갈 때 엄마께 하는 인사말은 어느 것인가요?","options":[{"t":"다녀오겠습니다.","correct":true},{"t":"다녀왔습니다.","mis":"K1-1-u5-X02"},{"t":"안녕히 주무세요.","mis":"K1-1-u5-X03"}],"explanation":["나갈 때는 「다녀오겠습니다.」예요.","나갈 때와 들어올 때 인사를 바꾸면 안 돼요.","「오겠습니다」는 갈 때, 「왔습니다」는 돌아왔을 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#15','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C8',2,'mc','auto','사슴이 숲에서 움직일 수 없었던 까닭은 무엇인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":15,"concept":"K1-1-u5-C8","difficulty":2,"kind":"mc","stem":"사슴이 숲에서 움직일 수 없었던 까닭은 무엇인가요?","options":[{"t":"뿔이 나뭇가지에 걸려서","correct":true},{"t":"다리를 다쳐서","mis":"K1-1-u5-X12"},{"t":"잠이 들어서","mis":"K1-1-u5-X12"}],"explanation":["뿔이 나뭇가지에 걸렸어요.","다른 두 보기는 이야기의 까닭과 달라요.","「무슨 일이? 왜?」를 이어 봐요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#16','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C9',2,'mc','auto','「사슴은」을 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],false,'{"seq":16,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"「사슴은」을 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[사스믄]","correct":true},{"t":"[사슴은]","mis":"K1-1-u5-X13"},{"t":"[사슴믄]","mis":"K1-1-u5-X14"}],"explanation":["받침이 뒤 ㅇ 자리로 넘어가 [사스믄]예요.","글자대로 읽거나 받침을 두 번 읽으면 안 돼요.","받침을 뒤로 옮겨 이어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
