INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#22','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C9',3,'ox','auto','「강아지」는 [가아지]로 소리 나요.',ARRAY['K1-1-u5-X15']::text[],false,'{"seq":22,"concept":"K1-1-u5-C9","difficulty":3,"kind":"ox","stem":"「강아지」는 [가아지]로 소리 나요.","answer":"X","reason_options":[{"t":"ㅇ 받침은 넘어가지 않아 [강아지]로 읽으니까","correct":true},{"t":"받침 뒤에 ㅇ이 오면 언제나 넘어가니까","mis":"K1-1-u5-X15"}],"mis":"K1-1-u5-X15","explanation":["「강아지」는 글자대로 [강아지]예요.","「앞 받침 + 뒤 ㅇ」 둘 다 맞아야 넘어가요 — ㅇ 받침은 그대로예요.","받침이 있는지, 무엇인지 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#23','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C4',4,'mc','auto','친구 집에서 놀다 나올 때예요. 나와 친구 엄마가 나눌 인사로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X07']::text[],false,'{"seq":23,"concept":"K1-1-u5-C4","difficulty":4,"kind":"mc","stem":"친구 집에서 놀다 나올 때예요. 나와 친구 엄마가 나눌 인사로 알맞은 것은 어느 것인가요?","options":[{"t":"나 「안녕히 계세요.」 — 친구 엄마 「그래, 잘 가렴.」","correct":true},{"t":"나 「잘 가.」 — 친구 엄마 「안녕히 계세요.」","mis":"K1-1-u5-X07"},{"t":"나 「안녕히 가세요.」 — 친구 엄마 「안녕히 계세요.」","mis":"K1-1-u5-X07"}],"explanation":["떠나는 나는 「안녕히 계세요.」예요.","떠나는 사람과 남는 사람의 말을 바꾸면 안 돼요.","누가 떠나고 누가 남는지 먼저 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#24','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C9',4,'mc','auto','「바람이 불어요.」를 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],false,'{"seq":24,"concept":"K1-1-u5-C9","difficulty":4,"kind":"mc","stem":"「바람이 불어요.」를 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[바라미 부러요]","correct":true},{"t":"[바람이 부러요]","mis":"K1-1-u5-X13"},{"t":"[바라미 불러요]","mis":"K1-1-u5-X14"}],"explanation":["두 곳 모두 받침이 뒤 ㅇ 자리로 넘어가 [바라미 부러요]예요.","한 곳만 넘기거나 받침을 두 번 읽으면 안 돼요.","문장 안 낱말마다 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_a#25','kor',1,1,'u5','','g1_1_kor_u5_review_a','unit_review','K1-1-u5-C10',4,'mc','auto','하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X05']::text[],false,'{"seq":25,"concept":"K1-1-u5-C10","difficulty":4,"kind":"mc","stem":"하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?","options":[{"t":"할아버지께 「안녕히 주무셨어요?」 → 도움 받고 「고마워.」 → 먹기 전 「잘 먹겠습니다.」","correct":true},{"t":"할아버지께 「잘 잤어?」 → 도움 받고 「고마워.」 → 먹기 전 「잘 먹겠습니다.」","mis":"K1-1-u5-X01"},{"t":"할아버지께 「안녕히 주무셨어요?」 → 도움 받고 「미안해.」 → 먹기 전 「잘 먹겠습니다.」","mis":"K1-1-u5-X05"}],"explanation":["상대와 상황에 모두 알맞아요.","다른 두 보기에는 상대나 상황에 맞지 않는 말이 하나씩 섞였어요.","한 줄씩 누구에게, 무슨 일인지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#1','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C1',1,'mc','auto','도움을 받았을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":1,"concept":"K1-1-u5-C1","difficulty":1,"kind":"mc","stem":"도움을 받았을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"고맙습니다.","correct":true},{"t":"고마워.","mis":"K1-1-u5-X01"},{"t":"안녕히 주무세요.","mis":"K1-1-u5-X03"}],"explanation":["도움을 받았을 때 웃어른께는 「고맙습니다.」 하고 인사해요.","「고마워.」는 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🤝"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#2','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C2',1,'mc','auto','집에 돌아왔을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X03']::text[],true,'{"seq":2,"concept":"K1-1-u5-C2","difficulty":1,"kind":"mc","stem":"집에 돌아왔을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"다녀왔습니다.","correct":true},{"t":"다녀오겠습니다.","mis":"K1-1-u5-X02"},{"t":"잘 먹었습니다.","mis":"K1-1-u5-X03"}],"explanation":["집에 돌아왔을 때 웃어른께는 「다녀왔습니다.」 하고 인사해요.","다른 인사말은 하는 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🏠"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#3','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C3',1,'ox','auto','친구에게 인사할 때 딴 곳을 보며 말해도 괜찮아요.',ARRAY['K1-1-u5-X04']::text[],false,'{"seq":3,"concept":"K1-1-u5-C3","difficulty":1,"kind":"ox","stem":"친구에게 인사할 때 딴 곳을 보며 말해도 괜찮아요.","answer":"X","reason_options":[{"t":"얼굴을 보며 인사해야 반가운 마음이 전해지니까","correct":true},{"t":"말만 하면 마음은 저절로 전해지니까","mis":"K1-1-u5-X04"}],"mis":"K1-1-u5-X04","explanation":["눈을 보며 인사해야 해요.","딴 곳을 보면 친구가 서운해요.","손 빼고, 눈 보고, 밝은 목소리로 인사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#4','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C4',1,'mc','auto','줄을 서다가 친구를 밀었어요. 먼저 할 말은 어느 것인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X06']::text[],false,'{"seq":4,"concept":"K1-1-u5-C4","difficulty":1,"kind":"mc","stem":"줄을 서다가 친구를 밀었어요. 먼저 할 말은 어느 것인가요?","options":[{"t":"미안해.","correct":true},{"t":"고마워.","mis":"K1-1-u5-X05"},{"t":"축하해.","mis":"K1-1-u5-X06"}],"explanation":["잘못했으니 「미안해.」 하고 사과해요.","다른 두 말은 이 상황에 맞지 않아요.","받았는지, 잘못했는지, 기쁜 일인지 살펴요."],"asset":{"type":"scene","icon":"🚶"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#5','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C6',1,'mc','auto','「달님도 잘 자요」에서 하늘에 있는 것 가운데 인사를 받은 것은 어느 것인가요?',ARRAY['K1-1-u5-X09']::text[],false,'{"seq":5,"concept":"K1-1-u5-C6","difficulty":1,"kind":"mc","stem":"「달님도 잘 자요」에서 하늘에 있는 것 가운데 인사를 받은 것은 어느 것인가요?","options":[{"t":"달님","correct":true},{"t":"해님","mis":"K1-1-u5-X09"},{"t":"별님","mis":"K1-1-u5-X09"}],"explanation":["하늘 달님에게 「잘 자요」라고 했어요.","다른 두 보기는 동시에 나오지 않거나 다른 줄이에요.","줄마다 누구에게, 무엇이라고 했는지 꼽아요."],"asset":{"type":"passage","lines":["하루가 저물고 달이 뜨면","엄마 아빠, 안녕히 주무세요","내 동생 콩이도 잘 자","마당 강아지도 잘 자","하늘 달님도 잘 자요","내일 아침 또 만나요"],"title":"달님도 잘 자요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#6','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C8',1,'mc','auto','사슴 앞에 나타난 동물은 누구인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":6,"concept":"K1-1-u5-C8","difficulty":1,"kind":"mc","stem":"사슴 앞에 나타난 동물은 누구인가요?","options":[{"t":"사자","correct":true},{"t":"곰","mis":"K1-1-u5-X12"},{"t":"늑대","mis":"K1-1-u5-X12"}],"explanation":["사자가 나타났어요.","다른 두 보기는 이야기에서 일어나지 않은 일이에요.","이야기를 차례대로 떠올려요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#7','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C9',1,'mc','auto','「먹이」는 어떻게 소리 나나요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],true,'{"seq":7,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"「먹이」는 어떻게 소리 나나요?","options":[{"t":"[머기]","correct":true},{"t":"[먹이]","mis":"K1-1-u5-X13"},{"t":"[먹기]","mis":"K1-1-u5-X14"}],"explanation":["「먹이」는 소리 내면 [머기] — 받침 ㄱ이 뒤 글자 ㅇ 자리로 넘어가요.","[먹이]처럼 글자대로 읽거나 [먹기]처럼 받침을 두 번 읽으면 안 돼요.","앞 글자 받침 뒤에 ㅇ이 오면 받침을 뒤로 옮겨 이어 읽어요."],"variant_rule":{"yeon":{"ask":"read","mis":{"keep":"X13","double":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#8','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C9',1,'mc','auto','글자와 소리가 다른 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X15']::text[],true,'{"seq":8,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"글자와 소리가 다른 낱말은 어느 것인가요?","options":[{"t":"웃음","correct":true},{"t":"나무","mis":"K1-1-u5-X15"},{"t":"모자","mis":"K1-1-u5-X15"}],"explanation":["「웃음」은 [우슴] 하고 소리 나서 글자와 달라요.","「나무」·「모자」는 글자대로 소리 나요.","앞 글자 받침 뒤에 ㅇ이 오면 소리가 달라져요 — 받침이 없거나 ㅇ 받침이면 그대로예요."],"variant_rule":{"yeon":{"ask":"diff","mis":{"same":"X15"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#9','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C1',2,'mc','auto','「죄송합니다.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X03']::text[],true,'{"seq":9,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"「죄송합니다.」는 언제 하는 인사말인가요?","options":[{"t":"잘못했을 때","correct":true},{"t":"도움을 받았을 때","mis":"K1-1-u5-X05"},{"t":"집을 나설 때","mis":"K1-1-u5-X03"}],"explanation":["「죄송합니다.」는 잘못했을 때 하는 인사말이에요.","다른 때에는 그때에 맞는 인사말이 따로 있어요.","인사말을 들으면 어떤 때인지 장면을 떠올려 봐요."],"variant_rule":{"greet":{"ask":"when","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#10','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C5',2,'mc','auto','친구가 「생일 축하해!」라고 했어요. 대답으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X08']::text[],false,'{"seq":10,"concept":"K1-1-u5-C5","difficulty":2,"kind":"mc","stem":"친구가 「생일 축하해!」라고 했어요. 대답으로 알맞은 것은 어느 것인가요?","options":[{"t":"고마워!","correct":true},{"t":"괜찮아.","mis":"K1-1-u5-X08"},{"t":"미안해.","mis":"K1-1-u5-X08"}],"explanation":["「생일 축하해!」에는 「고마워!」 하고 대답해요.","다른 두 말은 받은 인사에 맞지 않아요.","인사와 대답은 짝이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#11','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C7',2,'mc','auto','「아침 인사」에서 되풀이되는 말은 어느 것인가요?',ARRAY['K1-1-u5-X10']::text[],false,'{"seq":11,"concept":"K1-1-u5-C7","difficulty":2,"kind":"mc","stem":"「아침 인사」에서 되풀이되는 말은 어느 것인가요?","options":[{"t":"안녕?","correct":true},{"t":"방긋","mis":"K1-1-u5-X10"},{"t":"오늘도","mis":"K1-1-u5-X10"}],"explanation":["「안녕?」이 두 줄에 되풀이돼요.","다른 말은 한 번씩 나와요.","되풀이되는 말에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["창문 너머 해님이 방긋","할머니, 안녕히 주무셨어요?","참새야, 안녕?","나팔꽃아, 안녕?","오늘도 반갑게","인사로 시작해요"],"title":"아침 인사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#12','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C9',2,'mc','auto','글자와 소리가 같은 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X13']::text[],true,'{"seq":12,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"글자와 소리가 같은 낱말은 어느 것인가요?","options":[{"t":"강아지","correct":true},{"t":"연어","mis":"K1-1-u5-X13"},{"t":"낙엽","mis":"K1-1-u5-X13"}],"explanation":["「강아지」는 글자대로 소리 나요.","「연어」·「낙엽」은 받침이 뒤 ㅇ 자리로 넘어가 소리가 달라요.","받침이 없거나 ㅇ 받침이면 글자와 소리가 같아요."],"variant_rule":{"yeon":{"ask":"same","mis":{"diff":"X13"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#13','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C10',2,'mc','auto','아픈 친구에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X06','K1-1-u5-X03']::text[],false,'{"seq":13,"concept":"K1-1-u5-C10","difficulty":2,"kind":"mc","stem":"아픈 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"얼른 나아서 같이 놀자.","correct":true},{"t":"축하해!","mis":"K1-1-u5-X06"},{"t":"잘 먹겠습니다.","mis":"K1-1-u5-X03"}],"explanation":["아픈 친구를 위로해요.","다른 두 말은 이 상황과 어울리지 않아요.","친구 마음을 먼저 떠올려요."],"asset":{"type":"scene","icon":"🤒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#14','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C2',2,'mc','auto','학교에서 집에 돌아왔을 때 하는 인사말은 어느 것인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X03']::text[],false,'{"seq":14,"concept":"K1-1-u5-C2","difficulty":2,"kind":"mc","stem":"학교에서 집에 돌아왔을 때 하는 인사말은 어느 것인가요?","options":[{"t":"다녀왔습니다.","correct":true},{"t":"다녀오겠습니다.","mis":"K1-1-u5-X02"},{"t":"잘 먹겠습니다.","mis":"K1-1-u5-X03"}],"explanation":["돌아왔을 때는 「다녀왔습니다.」예요.","나갈 때와 들어올 때 인사를 바꾸면 안 돼요.","「오겠습니다」는 갈 때, 「왔습니다」는 돌아왔을 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#15','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C8',2,'mc','auto','사슴이 사자에게서 달아날 수 있었던 것은 무엇 덕분인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":15,"concept":"K1-1-u5-C8","difficulty":2,"kind":"mc","stem":"사슴이 사자에게서 달아날 수 있었던 것은 무엇 덕분인가요?","options":[{"t":"긴 다리","correct":true},{"t":"멋진 뿔","mis":"K1-1-u5-X12"},{"t":"큰 목소리","mis":"K1-1-u5-X12"}],"explanation":["긴 다리로 쌩쌩 달렸어요.","다른 두 보기는 이야기의 까닭과 달라요.","「무슨 일이? 왜?」를 이어 봐요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#16','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C9',2,'mc','auto','「뿔을」을 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],false,'{"seq":16,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"「뿔을」을 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[뿌를]","correct":true},{"t":"[뿔을]","mis":"K1-1-u5-X13"},{"t":"[뿔를]","mis":"K1-1-u5-X14"}],"explanation":["받침이 뒤 ㅇ 자리로 넘어가 [뿌를]예요.","글자대로 읽거나 받침을 두 번 읽으면 안 돼요.","받침을 뒤로 옮겨 이어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
