INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#20','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C9',3,'error','auto','다은이가 소리 나는 대로 적었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#21','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C7',3,'error','auto','태민이가 「(     )야, 안녕?」 틀로 바꿔 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#22','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C9',3,'ox','auto','「고양이」는 [고양이]로, 글자대로 소리 나요.',ARRAY['K1-1-u5-X15']::text[],false,'{"seq":22,"concept":"K1-1-u5-C9","difficulty":3,"kind":"ox","stem":"「고양이」는 [고양이]로, 글자대로 소리 나요.","answer":"O","reason_options":[{"t":"ㅇ 받침은 뒤 ㅇ 자리로 넘어가지 않으니까","correct":true},{"t":"받침이 있으면 언제나 소리가 바뀌니까","mis":"K1-1-u5-X15"}],"mis":"K1-1-u5-X15","explanation":["「고양이」는 글자대로 [고양이]예요.","「앞 받침 + 뒤 ㅇ」 둘 다 맞아야 넘어가요 — ㅇ 받침은 그대로예요.","받침이 있는지, 무엇인지 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#23','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C4',4,'mc','auto','우리 집에 놀러 오신 이모가 돌아가실 때예요. 내가 할 인사로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X07']::text[],false,'{"seq":23,"concept":"K1-1-u5-C4","difficulty":4,"kind":"mc","stem":"우리 집에 놀러 오신 이모가 돌아가실 때예요. 내가 할 인사로 알맞은 것은 어느 것인가요?","options":[{"t":"이모, 안녕히 가세요.","correct":true},{"t":"이모, 안녕히 계세요.","mis":"K1-1-u5-X07"},{"t":"이모, 잘 가.","mis":"K1-1-u5-X07"}],"explanation":["떠나는 이모께는 「안녕히 가세요.」예요.","떠나는 사람과 남는 사람의 말을 바꾸면 안 돼요.","누가 떠나고 누가 남는지 먼저 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#24','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C9',4,'mc','auto','「얼음이 녹아요.」를 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],false,'{"seq":24,"concept":"K1-1-u5-C9","difficulty":4,"kind":"mc","stem":"「얼음이 녹아요.」를 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[어르미 노가요]","correct":true},{"t":"[얼음이 노가요]","mis":"K1-1-u5-X13"},{"t":"[어르미 녹가요]","mis":"K1-1-u5-X14"}],"explanation":["두 곳 모두 받침이 뒤 ㅇ 자리로 넘어가 [어르미 노가요]예요.","한 곳만 넘기거나 받침을 두 번 읽으면 안 돼요.","문장 안 낱말마다 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_b#25','kor',1,1,'u5','','g1_1_kor_u5_review_b','unit_review','K1-1-u5-C10',4,'mc','auto','하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X06']::text[],false,'{"seq":25,"concept":"K1-1-u5-C10","difficulty":4,"kind":"mc","stem":"하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?","options":[{"t":"나설 때 「다녀오겠습니다.」 → 친구 상에 「축하해!」 → 잘 때 「안녕히 주무세요.」","correct":true},{"t":"나설 때 「다녀왔습니다.」 → 친구 상에 「축하해!」 → 잘 때 「안녕히 주무세요.」","mis":"K1-1-u5-X02"},{"t":"나설 때 「다녀오겠습니다.」 → 친구 상에 「미안해.」 → 잘 때 「안녕히 주무세요.」","mis":"K1-1-u5-X06"}],"explanation":["상대와 상황에 모두 알맞아요.","다른 두 보기에는 상대나 상황에 맞지 않는 말이 하나씩 섞였어요.","한 줄씩 누구에게, 무슨 일인지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#1','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C1',1,'mc','auto','잘못했을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":1,"concept":"K1-1-u5-C1","difficulty":1,"kind":"mc","stem":"잘못했을 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"죄송합니다.","correct":true},{"t":"미안해.","mis":"K1-1-u5-X01"},{"t":"축하드립니다.","mis":"K1-1-u5-X03"}],"explanation":["잘못했을 때 웃어른께는 「죄송합니다.」 하고 인사해요.","「미안해.」는 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"💥"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#2','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C2',1,'mc','auto','밥을 먹기 전에 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":2,"concept":"K1-1-u5-C2","difficulty":1,"kind":"mc","stem":"밥을 먹기 전에 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"잘 먹겠습니다.","correct":true},{"t":"잘 먹었습니다.","mis":"K1-1-u5-X03"},{"t":"안녕히 주무세요.","mis":"K1-1-u5-X03"}],"explanation":["밥을 먹기 전에 웃어른께는 「잘 먹겠습니다.」 하고 인사해요.","다른 인사말은 하는 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🍚"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#3','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C3',1,'ox','auto','인사는 작은 목소리로 중얼거려도 마음만 있으면 돼요.',ARRAY['K1-1-u5-X04']::text[],false,'{"seq":3,"concept":"K1-1-u5-C3","difficulty":1,"kind":"ox","stem":"인사는 작은 목소리로 중얼거려도 마음만 있으면 돼요.","answer":"X","reason_options":[{"t":"밝고 또렷한 목소리여야 마음이 잘 전해지니까","correct":true},{"t":"마음은 말하지 않아도 다 전해지니까","mis":"K1-1-u5-X04"}],"mis":"K1-1-u5-X04","explanation":["또렷하게 말해야 상대가 알아들어요.","중얼거리면 인사를 못 들을 수 있어요.","손 빼고, 눈 보고, 밝은 목소리로 인사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#4','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C4',1,'mc','auto','친구가 달리기에서 일등을 했어요. 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u5-X06','K1-1-u5-X05']::text[],false,'{"seq":4,"concept":"K1-1-u5-C4","difficulty":1,"kind":"mc","stem":"친구가 달리기에서 일등을 했어요. 알맞은 말은 어느 것인가요?","options":[{"t":"축하해!","correct":true},{"t":"미안해.","mis":"K1-1-u5-X06"},{"t":"고마워.","mis":"K1-1-u5-X05"}],"explanation":["기쁜 일이니 「축하해!」예요.","다른 두 말은 이 상황에 맞지 않아요.","받았는지, 잘못했는지, 기쁜 일인지 살펴요."],"asset":{"type":"scene","icon":"🏃"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#5','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C6',1,'mc','auto','「아침 인사」에서 「안녕?」 하고 인사를 받은 것은 어느 것인가요?',ARRAY['K1-1-u5-X09']::text[],false,'{"seq":5,"concept":"K1-1-u5-C6","difficulty":1,"kind":"mc","stem":"「아침 인사」에서 「안녕?」 하고 인사를 받은 것은 어느 것인가요?","options":[{"t":"참새","correct":true},{"t":"할머니","mis":"K1-1-u5-X09"},{"t":"강아지","mis":"K1-1-u5-X09"}],"explanation":["참새에게 「안녕?」이라고 했어요.","다른 두 보기는 동시에 나오지 않거나 다른 줄이에요.","줄마다 누구에게, 무엇이라고 했는지 꼽아요."],"asset":{"type":"passage","lines":["창문 너머 해님이 방긋","할머니, 안녕히 주무셨어요?","참새야, 안녕?","나팔꽃아, 안녕?","오늘도 반갑게","인사로 시작해요"],"title":"아침 인사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#6','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C8',1,'mc','auto','사슴의 뿔이 걸린 곳은 어디인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":6,"concept":"K1-1-u5-C8","difficulty":1,"kind":"mc","stem":"사슴의 뿔이 걸린 곳은 어디인가요?","options":[{"t":"나뭇가지","correct":true},{"t":"바위틈","mis":"K1-1-u5-X12"},{"t":"울타리","mis":"K1-1-u5-X12"}],"explanation":["숲에서 나뭇가지에 걸렸어요.","다른 두 보기는 이야기에서 일어나지 않은 일이에요.","이야기를 차례대로 떠올려요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#7','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C9',1,'mc','auto','「얼음」은 어떻게 소리 나나요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],true,'{"seq":7,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"「얼음」은 어떻게 소리 나나요?","options":[{"t":"[어름]","correct":true},{"t":"[얼음]","mis":"K1-1-u5-X13"},{"t":"[얼름]","mis":"K1-1-u5-X14"}],"explanation":["「얼음」은 소리 내면 [어름] — 받침 ㄹ이 뒤 글자 ㅇ 자리로 넘어가요.","[얼음]처럼 글자대로 읽거나 [얼름]처럼 받침을 두 번 읽으면 안 돼요.","앞 글자 받침 뒤에 ㅇ이 오면 받침을 뒤로 옮겨 이어 읽어요."],"variant_rule":{"yeon":{"ask":"read","mis":{"keep":"X13","double":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#8','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C9',1,'mc','auto','글자와 소리가 다른 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X15']::text[],true,'{"seq":8,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"글자와 소리가 다른 낱말은 어느 것인가요?","options":[{"t":"국어","correct":true},{"t":"가방","mis":"K1-1-u5-X15"},{"t":"사과","mis":"K1-1-u5-X15"}],"explanation":["「국어」는 [구거] 하고 소리 나서 글자와 달라요.","「가방」·「사과」는 글자대로 소리 나요.","앞 글자 받침 뒤에 ㅇ이 오면 소리가 달라져요 — 받침이 없거나 ㅇ 받침이면 그대로예요."],"variant_rule":{"yeon":{"ask":"diff","mis":{"same":"X15"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#9','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C1',2,'mc','auto','「안녕히 주무셨어요?」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":9,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"「안녕히 주무셨어요?」는 언제 하는 인사말인가요?","options":[{"t":"아침에 일어났을 때","correct":true},{"t":"잠자기 전에","mis":"K1-1-u5-X03"},{"t":"밥을 다 먹은 뒤에","mis":"K1-1-u5-X03"}],"explanation":["「안녕히 주무셨어요?」는 아침에 일어났을 때 하는 인사말이에요.","다른 때에는 그때에 맞는 인사말이 따로 있어요.","인사말을 들으면 어떤 때인지 장면을 떠올려 봐요."],"variant_rule":{"greet":{"ask":"when","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#10','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C5',2,'mc','auto','친구가 「연필 빌려줘서 고마워.」라고 했어요. 대답으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X08']::text[],false,'{"seq":10,"concept":"K1-1-u5-C5","difficulty":2,"kind":"mc","stem":"친구가 「연필 빌려줘서 고마워.」라고 했어요. 대답으로 알맞은 것은 어느 것인가요?","options":[{"t":"천만에.","correct":true},{"t":"미안해.","mis":"K1-1-u5-X08"},{"t":"축하해.","mis":"K1-1-u5-X08"}],"explanation":["「연필 빌려줘서 고마워.」에는 「천만에.」 하고 대답해요.","다른 두 말은 받은 인사에 맞지 않아요.","인사와 대답은 짝이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#11','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C7',2,'mc','auto','「(     )도 잘 자요」 틀에 맞게 바꿔 쓴 것은 어느 것인가요?',ARRAY['K1-1-u5-X11']::text[],false,'{"seq":11,"concept":"K1-1-u5-C7","difficulty":2,"kind":"mc","stem":"「(     )도 잘 자요」 틀에 맞게 바꿔 쓴 것은 어느 것인가요?","options":[{"t":"어항 물고기도 잘 자요","correct":true},{"t":"어항 물고기가 헤엄쳐요","mis":"K1-1-u5-X11"},{"t":"어항 물고기도 잘 자요 안녕 안녕","mis":"K1-1-u5-X11"}],"explanation":["빈칸만 바꾸고 나머지는 그대로예요.","다른 일로 바꾸거나 말을 덧붙이면 틀이 깨져요.","원래 줄 아래 나란히 써 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#12','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C9',2,'mc','auto','글자와 소리가 같은 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X13']::text[],true,'{"seq":12,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"글자와 소리가 같은 낱말은 어느 것인가요?","options":[{"t":"자동차","correct":true},{"t":"금요일","mis":"K1-1-u5-X13"},{"t":"발음","mis":"K1-1-u5-X13"}],"explanation":["「자동차」는 글자대로 소리 나요.","「금요일」·「발음」은 받침이 뒤 ㅇ 자리로 넘어가 소리가 달라요.","받침이 없거나 ㅇ 받침이면 글자와 소리가 같아요."],"variant_rule":{"yeon":{"ask":"same","mis":{"diff":"X13"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#13','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C10',2,'mc','auto','졸업하는 언니에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X03']::text[],false,'{"seq":13,"concept":"K1-1-u5-C10","difficulty":2,"kind":"mc","stem":"졸업하는 언니에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"졸업 축하해!","correct":true},{"t":"미안해.","mis":"K1-1-u5-X05"},{"t":"잘 자.","mis":"K1-1-u5-X03"}],"explanation":["기쁜 일이니 축하해요.","다른 두 말은 이 상황과 어울리지 않아요.","친구 마음을 먼저 떠올려요."],"asset":{"type":"scene","icon":"🎓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#14','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C2',2,'mc','auto','「다녀오겠습니다.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X03']::text[],false,'{"seq":14,"concept":"K1-1-u5-C2","difficulty":2,"kind":"mc","stem":"「다녀오겠습니다.」는 언제 하는 인사말인가요?","options":[{"t":"집을 나설 때","correct":true},{"t":"집에 돌아왔을 때","mis":"K1-1-u5-X02"},{"t":"잠자기 전에","mis":"K1-1-u5-X03"}],"explanation":["「다녀오겠습니다.」는 나설 때 해요.","나갈 때와 들어올 때 인사를 바꾸면 안 돼요.","「오겠습니다」는 갈 때, 「왔습니다」는 돌아왔을 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#15','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C8',2,'mc','auto','사슴이 다리를 보고 얼굴을 찡그린 까닭은 무엇인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":15,"concept":"K1-1-u5-C8","difficulty":2,"kind":"mc","stem":"사슴이 다리를 보고 얼굴을 찡그린 까닭은 무엇인가요?","options":[{"t":"다리가 너무 가늘다고 여겨서","correct":true},{"t":"다리가 너무 길어서","mis":"K1-1-u5-X12"},{"t":"다리를 다쳐서","mis":"K1-1-u5-X12"}],"explanation":["다리가 가늘다고 싫어했어요.","다른 두 보기는 이야기의 까닭과 달라요.","「무슨 일이? 왜?」를 이어 봐요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#16','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C9',2,'mc','auto','「물에」를 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],false,'{"seq":16,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"「물에」를 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[무레]","correct":true},{"t":"[물에]","mis":"K1-1-u5-X13"},{"t":"[물레]","mis":"K1-1-u5-X14"}],"explanation":["받침이 뒤 ㅇ 자리로 넘어가 [무레]예요.","글자대로 읽거나 받침을 두 번 읽으면 안 돼요.","받침을 뒤로 옮겨 이어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
