INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#18','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C4',3,'mc','auto','선생님께서 상을 받으셨어요. 가장 알맞은 인사말은 어느 것인가요?',ARRAY['K1-1-u5-X16','K1-1-u5-X01']::text[],false,'{"seq":18,"concept":"K1-1-u5-C4","difficulty":3,"kind":"mc","stem":"선생님께서 상을 받으셨어요. 가장 알맞은 인사말은 어느 것인가요?","options":[{"t":"축하드립니다.","correct":true},{"t":"안녕하세요?","mis":"K1-1-u5-X16"},{"t":"축하해!","mis":"K1-1-u5-X01"}],"explanation":["상을 받으셨으니 축하드려요.","늘 하던 인사는 오늘 있는 일을 놓쳤고, 반말은 웃어른께 맞지 않아요.","누구에게, 무슨 일인지 함께 살펴요."],"asset":{"type":"scene","icon":"🏆"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
