INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#21','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C7',3,'error','auto','하린이가 「(     )도 잘 자요」 틀로 바꿔 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#22','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C9',3,'ox','auto','「다리미」는 글자와 소리가 달라요.',ARRAY['K1-1-u5-X15']::text[],false,'{"seq":22,"concept":"K1-1-u5-C9","difficulty":3,"kind":"ox","stem":"「다리미」는 글자와 소리가 달라요.","answer":"X","reason_options":[{"t":"받침이 없어서 글자대로 [다리미]로 읽으니까","correct":true},{"t":"세 글자 낱말은 소리가 바뀌니까","mis":"K1-1-u5-X15"}],"mis":"K1-1-u5-X15","explanation":["「다리미」는 글자대로 [다리미]예요.","「앞 받침 + 뒤 ㅇ」 둘 다 맞아야 넘어가요 — ㅇ 받침은 그대로예요.","받침이 있는지, 무엇인지 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#23','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C4',4,'mc','auto','학원에서 집에 갈 때 선생님께 할 인사로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X07']::text[],false,'{"seq":23,"concept":"K1-1-u5-C4","difficulty":4,"kind":"mc","stem":"학원에서 집에 갈 때 선생님께 할 인사로 알맞은 것은 어느 것인가요?","options":[{"t":"선생님, 안녕히 계세요.","correct":true},{"t":"선생님, 안녕히 가세요.","mis":"K1-1-u5-X07"},{"t":"선생님, 잘 가요.","mis":"K1-1-u5-X07"}],"explanation":["내가 떠나니 남는 선생님께 「안녕히 계세요.」예요.","떠나는 사람과 남는 사람의 말을 바꾸면 안 돼요.","누가 떠나고 누가 남는지 먼저 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#24','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C9',4,'mc','auto','「목요일에 놀아요.」를 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],false,'{"seq":24,"concept":"K1-1-u5-C9","difficulty":4,"kind":"mc","stem":"「목요일에 놀아요.」를 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[모교이레 노라요]","correct":true},{"t":"[목요일에 노라요]","mis":"K1-1-u5-X13"},{"t":"[모교이레 놀라요]","mis":"K1-1-u5-X14"}],"explanation":["두 곳 모두 받침이 뒤 ㅇ 자리로 넘어가 [모교이레 노라요]예요.","한 곳만 넘기거나 받침을 두 번 읽으면 안 돼요.","문장 안 낱말마다 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_c#25','kor',1,1,'u5','','g1_1_kor_u5_review_c','unit_review','K1-1-u5-C10',4,'mc','auto','하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X05']::text[],false,'{"seq":25,"concept":"K1-1-u5-C10","difficulty":4,"kind":"mc","stem":"하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?","options":[{"t":"선생님께 「안녕하세요?」 → 부딪친 친구에게 「미안해.」 → 돌아와서 「다녀왔습니다.」","correct":true},{"t":"선생님께 「안녕?」 → 부딪친 친구에게 「미안해.」 → 돌아와서 「다녀왔습니다.」","mis":"K1-1-u5-X01"},{"t":"선생님께 「안녕하세요?」 → 부딪친 친구에게 「고마워.」 → 돌아와서 「다녀왔습니다.」","mis":"K1-1-u5-X05"}],"explanation":["상대와 상황에 모두 알맞아요.","다른 두 보기에는 상대나 상황에 맞지 않는 말이 하나씩 섞였어요.","한 줄씩 누구에게, 무슨 일인지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#1','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C1',1,'mc','auto','헤어질 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X01','K1-1-u5-X03']::text[],true,'{"seq":1,"concept":"K1-1-u5-C1","difficulty":1,"kind":"mc","stem":"헤어질 때 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"안녕히 가세요.","correct":true},{"t":"잘 가.","mis":"K1-1-u5-X01"},{"t":"잘 먹겠습니다.","mis":"K1-1-u5-X03"}],"explanation":["헤어질 때 웃어른께는 「안녕히 가세요.」 하고 인사해요.","「잘 가.」는 친구에게 하는 말이고, 다른 인사말은 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🚶"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","reg":"X01","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#2','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C2',1,'mc','auto','잠자기 전에 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":2,"concept":"K1-1-u5-C2","difficulty":1,"kind":"mc","stem":"잠자기 전에 웃어른께 하는 인사말로 알맞은 것은 어느 것인가요?","options":[{"t":"안녕히 주무세요.","correct":true},{"t":"안녕히 주무셨어요?","mis":"K1-1-u5-X03"},{"t":"다녀오겠습니다.","mis":"K1-1-u5-X03"}],"explanation":["잠자기 전에 웃어른께는 「안녕히 주무세요.」 하고 인사해요.","다른 인사말은 하는 때가 달라요.","언제인지, 누구에게 하는지 두 가지를 함께 살펴요."],"asset":{"type":"scene","icon":"🌙"},"variant_rule":{"greet":{"ask":"say","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#3','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C3',1,'ox','auto','주머니에 손을 넣은 채 선생님께 인사하는 것은 바르지 않아요.',ARRAY['K1-1-u5-X04']::text[],false,'{"seq":3,"concept":"K1-1-u5-C3","difficulty":1,"kind":"ox","stem":"주머니에 손을 넣은 채 선생님께 인사하는 것은 바르지 않아요.","answer":"O","reason_options":[{"t":"웃어른께는 손을 빼고 공손히 인사해야 하니까","correct":true},{"t":"주머니에 손을 넣어야 멋있으니까","mis":"K1-1-u5-X04"}],"mis":"K1-1-u5-X04","explanation":["손을 빼고 인사하는 것이 바른 자세예요.","공손한 자세로 마음을 전해요.","손 빼고, 눈 보고, 밝은 목소리로 인사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#4','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C4',1,'mc','auto','친구가 우산을 함께 쓰자고 했어요. 알맞은 말은 어느 것인가요?',ARRAY['K1-1-u5-X05','K1-1-u5-X03']::text[],false,'{"seq":4,"concept":"K1-1-u5-C4","difficulty":1,"kind":"mc","stem":"친구가 우산을 함께 쓰자고 했어요. 알맞은 말은 어느 것인가요?","options":[{"t":"고마워.","correct":true},{"t":"미안해.","mis":"K1-1-u5-X05"},{"t":"잘 자.","mis":"K1-1-u5-X03"}],"explanation":["도움을 받았으니 「고마워.」예요.","다른 두 말은 이 상황에 맞지 않아요.","받았는지, 잘못했는지, 기쁜 일인지 살펴요."],"asset":{"type":"scene","icon":"☂️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#5','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C6',1,'mc','auto','「아침 인사」는 언제 하는 인사를 담았나요?',ARRAY['K1-1-u5-X09']::text[],false,'{"seq":5,"concept":"K1-1-u5-C6","difficulty":1,"kind":"mc","stem":"「아침 인사」는 언제 하는 인사를 담았나요?","options":[{"t":"아침에 일어났을 때","correct":true},{"t":"잠자기 전 저녁","mis":"K1-1-u5-X09"},{"t":"밥을 먹기 전","mis":"K1-1-u5-X09"}],"explanation":["해님이 방긋 웃는 아침 인사예요.","다른 두 보기는 동시에 나오지 않거나 다른 줄이에요.","줄마다 누구에게, 무엇이라고 했는지 꼽아요."],"asset":{"type":"passage","lines":["창문 너머 해님이 방긋","할머니, 안녕히 주무셨어요?","참새야, 안녕?","나팔꽃아, 안녕?","오늘도 반갑게","인사로 시작해요"],"title":"아침 인사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#6','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C8',1,'mc','auto','사슴이 처음에 가늘다고 싫어한 것은 무엇인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":6,"concept":"K1-1-u5-C8","difficulty":1,"kind":"mc","stem":"사슴이 처음에 가늘다고 싫어한 것은 무엇인가요?","options":[{"t":"다리","correct":true},{"t":"뿔","mis":"K1-1-u5-X12"},{"t":"귀","mis":"K1-1-u5-X12"}],"explanation":["다리가 너무 가늘다고 찡그렸어요.","다른 두 보기는 이야기에서 일어나지 않은 일이에요.","이야기를 차례대로 떠올려요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#7','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C9',1,'mc','auto','「놀이」는 어떻게 소리 나나요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],true,'{"seq":7,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"「놀이」는 어떻게 소리 나나요?","options":[{"t":"[노리]","correct":true},{"t":"[놀이]","mis":"K1-1-u5-X13"},{"t":"[놀리]","mis":"K1-1-u5-X14"}],"explanation":["「놀이」는 소리 내면 [노리] — 받침 ㄹ이 뒤 글자 ㅇ 자리로 넘어가요.","[놀이]처럼 글자대로 읽거나 [놀리]처럼 받침을 두 번 읽으면 안 돼요.","앞 글자 받침 뒤에 ㅇ이 오면 받침을 뒤로 옮겨 이어 읽어요."],"variant_rule":{"yeon":{"ask":"read","mis":{"keep":"X13","double":"X14"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#8','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C9',1,'mc','auto','글자와 소리가 다른 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X15']::text[],true,'{"seq":8,"concept":"K1-1-u5-C9","difficulty":1,"kind":"mc","stem":"글자와 소리가 다른 낱말은 어느 것인가요?","options":[{"t":"음악","correct":true},{"t":"기차","mis":"K1-1-u5-X15"},{"t":"포도","mis":"K1-1-u5-X15"}],"explanation":["「음악」은 [으막] 하고 소리 나서 글자와 달라요.","「기차」·「포도」는 글자대로 소리 나요.","앞 글자 받침 뒤에 ㅇ이 오면 소리가 달라져요 — 받침이 없거나 ㅇ 받침이면 그대로예요."],"variant_rule":{"yeon":{"ask":"diff","mis":{"same":"X15"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#9','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C1',2,'mc','auto','「축하드립니다.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X03']::text[],true,'{"seq":9,"concept":"K1-1-u5-C1","difficulty":2,"kind":"mc","stem":"「축하드립니다.」는 언제 하는 인사말인가요?","options":[{"t":"좋은 일을 축하할 때","correct":true},{"t":"잘못했을 때","mis":"K1-1-u5-X03"},{"t":"집에 돌아왔을 때","mis":"K1-1-u5-X03"}],"explanation":["「축하드립니다.」는 좋은 일을 축하할 때 하는 인사말이에요.","다른 때에는 그때에 맞는 인사말이 따로 있어요.","인사말을 들으면 어떤 때인지 장면을 떠올려 봐요."],"variant_rule":{"greet":{"ask":"when","to":"elder","mis":{"sit":"X03","inout":"X02","ts":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#10','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C5',2,'mc','auto','친구가 「내일 보자, 안녕!」이라고 했어요. 대답으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X08']::text[],false,'{"seq":10,"concept":"K1-1-u5-C5","difficulty":2,"kind":"mc","stem":"친구가 「내일 보자, 안녕!」이라고 했어요. 대답으로 알맞은 것은 어느 것인가요?","options":[{"t":"그래, 안녕!","correct":true},{"t":"잘 먹겠습니다.","mis":"K1-1-u5-X08"},{"t":"미안해.","mis":"K1-1-u5-X08"}],"explanation":["「내일 보자, 안녕!」에는 「그래, 안녕!」 하고 대답해요.","다른 두 말은 받은 인사에 맞지 않아요.","인사와 대답은 짝이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#11','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C7',2,'mc','auto','「(     )야, 안녕?」 틀에 맞게 바꿔 쓴 것은 어느 것인가요?',ARRAY['K1-1-u5-X11']::text[],false,'{"seq":11,"concept":"K1-1-u5-C7","difficulty":2,"kind":"mc","stem":"「(     )야, 안녕?」 틀에 맞게 바꿔 쓴 것은 어느 것인가요?","options":[{"t":"나비야, 안녕?","correct":true},{"t":"나비가 날아요","mis":"K1-1-u5-X11"},{"t":"나비야, 잘 먹겠습니다","mis":"K1-1-u5-X11"}],"explanation":["빈칸만 바꾸고 「야, 안녕?」은 그대로예요.","다른 일이나 다른 인사말로 바꾸면 틀이 깨져요.","원래 줄 아래 나란히 써 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#12','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C9',2,'mc','auto','글자와 소리가 같은 낱말은 어느 것인가요?',ARRAY['K1-1-u5-X13']::text[],true,'{"seq":12,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"글자와 소리가 같은 낱말은 어느 것인가요?","options":[{"t":"고양이","correct":true},{"t":"문어","mis":"K1-1-u5-X13"},{"t":"목욕","mis":"K1-1-u5-X13"}],"explanation":["「고양이」는 글자대로 소리 나요.","「문어」·「목욕」은 받침이 뒤 ㅇ 자리로 넘어가 소리가 달라요.","받침이 없거나 ㅇ 받침이면 글자와 소리가 같아요."],"variant_rule":{"yeon":{"ask":"same","mis":{"diff":"X13"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#13','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C10',2,'mc','auto','넘어진 친구에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X06','K1-1-u5-X05']::text[],false,'{"seq":13,"concept":"K1-1-u5-C10","difficulty":2,"kind":"mc","stem":"넘어진 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"괜찮아? 많이 아프지?","correct":true},{"t":"축하해!","mis":"K1-1-u5-X06"},{"t":"고마워.","mis":"K1-1-u5-X05"}],"explanation":["다친 친구를 걱정하고 위로해요.","다른 두 말은 이 상황과 어울리지 않아요.","친구 마음을 먼저 떠올려요."],"asset":{"type":"scene","icon":"🩹"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#14','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C2',2,'mc','auto','「다녀왔습니다.」는 언제 하는 인사말인가요?',ARRAY['K1-1-u5-X02','K1-1-u5-X03']::text[],false,'{"seq":14,"concept":"K1-1-u5-C2","difficulty":2,"kind":"mc","stem":"「다녀왔습니다.」는 언제 하는 인사말인가요?","options":[{"t":"집에 돌아왔을 때","correct":true},{"t":"집을 나설 때","mis":"K1-1-u5-X02"},{"t":"밥을 먹기 전에","mis":"K1-1-u5-X03"}],"explanation":["「다녀왔습니다.」는 돌아왔을 때 해요.","나갈 때와 들어올 때 인사를 바꾸면 안 돼요.","「오겠습니다」는 갈 때, 「왔습니다」는 돌아왔을 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#15','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C8',2,'mc','auto','사슴이 뿔에서 빠져나올 수 있었던 방법은 무엇인가요?',ARRAY['K1-1-u5-X12']::text[],false,'{"seq":15,"concept":"K1-1-u5-C8","difficulty":2,"kind":"mc","stem":"사슴이 뿔에서 빠져나올 수 있었던 방법은 무엇인가요?","options":[{"t":"머리를 힘껏 흔들어서","correct":true},{"t":"사자가 도와줘서","mis":"K1-1-u5-X12"},{"t":"뿔을 잘라서","mis":"K1-1-u5-X12"}],"explanation":["머리를 힘껏 흔들어 빠져나왔어요.","다른 두 보기는 이야기의 까닭과 달라요.","「무슨 일이? 왜?」를 이어 봐요."],"asset":{"type":"passage","lines":["숲속 연못가에 사슴 한 마리가 살았어요.","사슴은 물에 비친 뿔을 보며 말했어요. \"내 뿔은 정말 멋져!\"","그런데 가느다란 다리를 보고는 얼굴을 찡그렸어요. \"다리는 너무 가늘어.\"","그때 사자가 나타났어요. 사슴은 긴 다리로 쌩쌩 달렸어요.","숲으로 들어가자 뿔이 나뭇가지에 걸려 움직일 수 없었어요.","사슴은 머리를 힘껏 흔들어 겨우 빠져나왔어요.","\"내가 싫어하던 다리 덕분에 살았구나.\""],"title":"사슴과 뿔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#16','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C9',2,'mc','auto','「얼굴을」을 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],false,'{"seq":16,"concept":"K1-1-u5-C9","difficulty":2,"kind":"mc","stem":"「얼굴을」을 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[얼구를]","correct":true},{"t":"[얼굴을]","mis":"K1-1-u5-X13"},{"t":"[얼굴를]","mis":"K1-1-u5-X14"}],"explanation":["받침이 뒤 ㅇ 자리로 넘어가 [얼구를]예요.","글자대로 읽거나 받침을 두 번 읽으면 안 돼요.","받침을 뒤로 옮겨 이어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
