INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#22','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C9',3,'ox','auto','「우유」는 글자대로 [우유]로 소리 나요.',ARRAY['K1-1-u5-X15']::text[],false,'{"seq":22,"concept":"K1-1-u5-C9","difficulty":3,"kind":"ox","stem":"「우유」는 글자대로 [우유]로 소리 나요.","answer":"O","reason_options":[{"t":"받침이 없어 넘어갈 받침이 없으니까","correct":true},{"t":"ㅇ으로 시작하는 글자가 두 개라서 바뀌니까","mis":"K1-1-u5-X15"}],"mis":"K1-1-u5-X15","explanation":["「우유」는 글자대로 [우유]예요.","「앞 받침 + 뒤 ㅇ」 둘 다 맞아야 넘어가요 — ㅇ 받침은 그대로예요.","받침이 있는지, 무엇인지 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#23','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C4',4,'mc','auto','놀이터에서 먼저 집에 가는 친구에게 할 인사로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X07']::text[],false,'{"seq":23,"concept":"K1-1-u5-C4","difficulty":4,"kind":"mc","stem":"놀이터에서 먼저 집에 가는 친구에게 할 인사로 알맞은 것은 어느 것인가요?","options":[{"t":"잘 가, 내일 봐.","correct":true},{"t":"안녕히 계세요.","mis":"K1-1-u5-X07"},{"t":"안녕히 가세요.","mis":"K1-1-u5-X07"}],"explanation":["떠나는 친구에게는 「잘 가.」예요.","떠나는 사람과 남는 사람의 말을 바꾸면 안 돼요.","누가 떠나고 누가 남는지 먼저 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#24','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C9',4,'mc','auto','「악어가 웃어요.」를 바르게 소리 낸 것은 어느 것인가요?',ARRAY['K1-1-u5-X13','K1-1-u5-X14']::text[],false,'{"seq":24,"concept":"K1-1-u5-C9","difficulty":4,"kind":"mc","stem":"「악어가 웃어요.」를 바르게 소리 낸 것은 어느 것인가요?","options":[{"t":"[아거가 우서요]","correct":true},{"t":"[악어가 우서요]","mis":"K1-1-u5-X13"},{"t":"[아거가 웃서요]","mis":"K1-1-u5-X14"}],"explanation":["두 곳 모두 받침이 뒤 ㅇ 자리로 넘어가 [아거가 우서요]예요.","한 곳만 넘기거나 받침을 두 번 읽으면 안 돼요.","문장 안 낱말마다 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u5_review_d#25','kor',1,1,'u5','','g1_1_kor_u5_review_d','unit_review','K1-1-u5-C10',4,'mc','auto','하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u5-X06','K1-1-u5-X03']::text[],false,'{"seq":25,"concept":"K1-1-u5-C10","difficulty":4,"kind":"mc","stem":"하루 이야기에서 인사말이 모두 알맞은 것은 어느 것인가요?","options":[{"t":"아픈 짝에게 「얼른 나아.」 → 다 먹고 「잘 먹었습니다.」 → 동생에게 「잘 자.」","correct":true},{"t":"아픈 짝에게 「축하해!」 → 다 먹고 「잘 먹었습니다.」 → 동생에게 「잘 자.」","mis":"K1-1-u5-X06"},{"t":"아픈 짝에게 「얼른 나아.」 → 다 먹고 「잘 먹겠습니다.」 → 동생에게 「잘 자.」","mis":"K1-1-u5-X03"}],"explanation":["상대와 상황에 모두 알맞아요.","다른 두 보기에는 상대나 상황에 맞지 않는 말이 하나씩 섞였어요.","한 줄씩 누구에게, 무슨 일인지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
